import json, sys

# Read-only: for each given log slice, count transcript user+assistant lines
# inside that slice's [first ts, last ts] window and print events/lines, so
# the newest slice's ratio can be compared with older ones.
transcript, slices = sys.argv[1], sys.argv[2:]

windows = []
for path in slices:
    ts = []
    with open(path, "rb") as fh:
        for line in fh:
            if line.strip():
                ts.append(str(json.loads(line).get("ts", ""))[:19])
    windows.append([path.split("\\")[-2], min(ts), max(ts), len(ts), 0])

with open(transcript, "rb") as fh:
    for line in fh:
        e = json.loads(line)
        if e.get("type") not in ("user", "assistant"):
            continue
        t = str(e.get("timestamp") or "")[:19]
        for w in windows:
            if w[1] <= t <= w[2]:
                w[4] += 1

for name, lo, hi, events, lines in windows:
    ratio = events / lines if lines else float("nan")
    print(f"{name}: events={events} user+assistant lines={lines} ratio={ratio:.2f}")

