windows = []
for path in slices:
    ts = []
    with open(path, "rb") as fh:
        for line in fh:
            if not line.strip():
                continue
            try:
                t = str(json.loads(line).get("ts") or "")[:19]
            except ValueError:
                continue
            if t:
                ts.append(t)
    if ts:
        windows.append([path.split("\\")[-2], min(ts), max(ts), len(ts), 0])

with open(transcript, "rb") as fh:
    for line in fh:
        try:
            e = json.loads(line)
        except ValueError:
            continue
        if e.get("type") not in ("user", "assistant"):
            continue
        t = str(e.get("timestamp") or "")[:19]
        for w in windows:
            if t and w[1] <= t <= w[2]:
                w[4] += 1

for name, lo, hi, events, lines in windows:
    ratio = events / lines if lines else float("nan")
    print(f"{name}: {lo[:16]}..{hi[:16]} events={events}"
          f" user+assistant lines={lines} ratio={ratio:.2f}")

