3745	static void ag_poll(long now)
3746	{
3747	  if (g_ag_seq != g_ag_seen)
3748	    {
3749	      pthread_mutex_lock(&g_ag_lock);
3750	      g_ag_seen  = g_ag_seq;           /* newest wins; a start+reply pair that
3751	                                        * lands in one 20 ms pass shows as the
3752	                                        * reply, with its question */
3753	      g_ag_state = g_ag_in_state;
3754	      g_ag_hb    = g_ag_in_hb;
3755	      g_ag_ok    = g_ag_in_ok;
3756	      memcpy(g_ag_q, g_ag_in_q, sizeof(g_ag_q));
3757	      memcpy(g_ag_a, g_ag_in_a, sizeof(g_ag_a));
3758	      pthread_mutex_unlock(&g_ag_lock);
3759	
3760	      g_ag_t0      = now;
3761	      g_ag_hide_at = 0;
3762	      g_ag_last_s  = -1;
3763	
3764	      if (g_ag_hb && g_ag_state == AG_REPLIED)
3765	        {
3766	          g_ag_min   = wall_min();
3767	          g_ag_alert = !g_ag_ok;
3768	          if (g_ag_ok)
3769	            {
3770	              g_ag_hide_at = now + AG_OK_SHOW_MS;
3771	            }
3772	          else
3773	            {
3774	              memcpy(g_ag_txt, g_ag_a, sizeof(g_ag_txt));
3775	            }
3776	
3777	          update_bell();
3778	        }
3779	      else if (g_ag_hb && g_ag_state != AG_WORKING)
3780	        {
3781	          g_ag_state = AG_IDLE;        /* a failed heartbeat is not news */
3782	        }
3783	      else if (g_ag_state != AG_WORKING)
3784	        {
3785	          g_ag_hide_at = now + AG_REPLY_SHOW_MS;
3786	        }
3787	
3788	      g_ag_shown = (g_ag_state != AG_IDLE);
3789	      if (g_ag_toast != NULL && !g_ag_shown)
3790	        {
3791	          lv_obj_add_flag(g_ag_toast, LV_OBJ_FLAG_HIDDEN);
3792	        }
3793	
3794	      ag_render(now);
3795	    }
3796	  else if (g_ag_state == AG_WORKING)
3797	    {
3798	      if (now - g_ag_t0 > AG_STUCK_MS)
3799	        {
3800	          /* no end-of-turn ever came (a path in agent_loop that drops the
3801	           * message without replying): stop counting forever */
3802	
3803	          g_ag_state   = g_ag_hb ? AG_IDLE : AG_FAILED;
3804	          g_ag_shown   = (g_ag_state != AG_IDLE);
3805	          g_ag_hide_at = now + AG_REPLY_SHOW_MS;
3806	          if (g_ag_toast != NULL && !g_ag_shown)
3807	            {
3808	              lv_obj_add_flag(g_ag_toast, LV_OBJ_FLAG_HIDDEN);
3809	            }
3810	
3811	          ag_render(now);
3812	        }
3813	      else if (!g_ag_hb && (int)((now - g_ag_t0) / 1000) != g_ag_last_s)
3814	        {
3815	          ag_render(now);
3816	        }
3817	    }
3818	
3819	  if (g_ag_hide_at != 0 && now >= g_ag_hide_at)
3820	    {
3821	      g_ag_hide_at = 0;
3822	      g_ag_shown   = 0;
3823	      if (g_ag_toast != NULL)
3824	        {
3825	          lv_obj_add_flag(g_ag_toast, LV_OBJ_FLAG_HIDDEN);
3826	        }
3827	    }
3828	}
