41	static int axp_wr(struct i2c_master_s *i,uint8_t r,uint8_t v){struct i2c_msg_s m;uint8_t b[2];b[0]=r;b[1]=v;m.frequency=400000;m.addr=0x34;m.flags=0;m.buffer=b;m.length=2;return I2C_TRANSFER(i,&m,1);}
42	static void axp_power(struct i2c_master_s *i){axp_wr(i,0x80,0x01);axp_wr(i,0x82,(3300-1500)/100);axp_wr(i,0x90,0x00);axp_wr(i,0x91,0x00);nxsig_usleep(5000);axp_wr(i,0x92,(3300-500)/100);axp_wr(i,0x96,(1500-500)/100);axp_wr(i,0x97,(2800-500)/100);axp_wr(i,0x90,0x31);nxsig_usleep(120000);}
