44	/* ---- PCF85063 RTC on the same I2C bus (addr 0x51) -------------------------
45	 * The board has a real battery-backed RTC chip. We drive it DIRECTLY over I2C
46	 * instead of via NuttX's CONFIG_RTC framework -- enabling that framework pulls
47	 * in ESP32S3_RT_TIMER and kills the USB CDC console (proven, 3 attempts). This
48	 * way we get persistent time with ZERO config changes and no USB risk.
49	 * Time regs 0x04..0x0A = sec(+OS flag) min hour day weekday month year, BCD. */
50	#define PCF_ADDR 0x51
51	static struct i2c_master_s *g_rtc_i2c;
52	
53	static int pcf_rd(struct i2c_master_s *i, uint8_t reg, uint8_t *buf, int len)
54	{
55	  struct i2c_msg_s m[2];
56	  m[0].frequency=400000; m[0].addr=PCF_ADDR; m[0].flags=0;
57	  m[0].buffer=&reg;      m[0].length=1;
58	  m[1].frequency=400000; m[1].addr=PCF_ADDR; m[1].flags=I2C_M_READ;
59	  m[1].buffer=buf;       m[1].length=len;
60	  return I2C_TRANSFER(i, m, 2);
61	}
62	static int pcf_wr(struct i2c_master_s *i, uint8_t reg, const uint8_t *buf, int len)
63	{
64	  struct i2c_msg_s m; uint8_t b[8];
65	  if (len > 7) return -1;
66	  b[0] = reg; memcpy(&b[1], buf, len);
67	  m.frequency=400000; m.addr=PCF_ADDR; m.flags=0; m.buffer=b; m.length=len+1;
68	  return I2C_TRANSFER(i, &m, 1);
69	}
70	static inline int     bcd2dec(uint8_t v){ return (v >> 4) * 10 + (v & 0x0f); }
71	static inline uint8_t dec2bcd(int v)    { return (uint8_t)(((v / 10) << 4) | (v % 10)); }
72	
73	/* civil date <-> days since 1970-01-01 (no localtime/mktime needed) */
74	static long days_from_civil(int y, int m, int d)
75	{
76	  y -= (m <= 2);
77	  long era = (y >= 0 ? y : y - 399) / 400;
78	  int  yoe = (int)(y - era * 400);
79	  int  doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
80	  int  doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
81	  return era * 146097L + doe - 719468;
82	}
83	static void civil_from_days(long z, int *y, int *m, int *d)
84	{
85	  z += 719468;
86	  long era = (z >= 0 ? z : z - 146096) / 146097;
87	  int  doe = (int)(z - era * 146097);
88	  int  yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
89	  long yy  = yoe + era * 400;
90	  int  doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
91	  int  mp  = (5 * doy + 2) / 153;
92	  int  dd  = doy - (153 * mp + 2) / 5 + 1;
93	  int  mm  = mp + (mp < 10 ? 3 : -9);
94	  *y = (int)(yy + (mm <= 2)); *m = mm; *d = dd;
95	}
96	
97	/* Persist the given time into the RTC chip (velapaw calls this on Set Clock). */
98	int board_rtc_settime(time_t t)
99	{
100	  uint8_t b[7]; int y, mo, d;
101	  long days = (long)(t / 86400);
102	  int  rem  = (int)(t % 86400);
103	  if (g_rtc_i2c == NULL) return -1;
104	  civil_from_days(days, &y, &mo, &d);
105	  b[0] = dec2bcd(rem % 60);          /* seconds; bit7 OS=0 marks time valid */
106	  b[1] = dec2bcd((rem / 60) % 60);
107	  b[2] = dec2bcd(rem / 3600);        /* 24h */
108	  b[3] = dec2bcd(d);
109	  b[4] = 0;                          /* weekday (unused) */
110	  b[5] = dec2bcd(mo);
111	  b[6] = dec2bcd((y - 2000) % 100);
112	  return pcf_wr(g_rtc_i2c, 0x04, b, 7);
113	}
114	
115	/* Read the RTC chip. 0 = ok, -1 = absent or oscillator stopped (never set). */
116	static int board_rtc_gettime(time_t *t)
117	{
118	  uint8_t b[7]; int y, mo, d, hh, mi, ss;
119	  if (g_rtc_i2c == NULL) return -1;
120	  if (pcf_rd(g_rtc_i2c, 0x04, b, 7) < 0) return -1;
121	  if (b[0] & 0x80) return -1;        /* OS flag: clock lost power, invalid */
122	  ss = bcd2dec(b[0] & 0x7f);
123	  mi = bcd2dec(b[1] & 0x7f);
124	  hh = bcd2dec(b[2] & 0x3f);
125	  d  = bcd2dec(b[3] & 0x3f);
126	  mo = bcd2dec(b[5] & 0x1f);
127	  y  = 2000 + bcd2dec(b[6]);
128	  if (mo < 1 || mo > 12 || d < 1 || d > 31 || hh > 23) return -1;
129	  *t = (time_t)(days_from_civil(y, mo, d) * 86400L + hh * 3600 + mi * 60 + ss);

