441	static void step_coils(uint8_t m)
442	{
443	  esp32s3_gpiowrite(STEP_IN1, (m & 0x1) != 0);
444	  esp32s3_gpiowrite(STEP_IN2, (m & 0x2) != 0);
445	  esp32s3_gpiowrite(STEP_IN3, (m & 0x4) != 0);
446	  esp32s3_gpiowrite(STEP_IN4, (m & 0x8) != 0);
447	}
