449	/* Claim all four coil lines as plain GPIO outputs. MUST be re-called right
450	 * before every dispense: other subsystems (and the UART0 mux) can steal a pin
451	 * back between feeds, and a silently re-muxed coil is exactly the failure that
452	 * looks like "the motor buzzes but won't turn".
453	 */
454	static void feeder_pins_output(void)
455	{
456	  esp32s3_configgpio(STEP_IN1, OUTPUT);
457	  esp32s3_configgpio(STEP_IN2, OUTPUT);
458	  esp32s3_configgpio(STEP_IN3, OUTPUT);
459	  esp32s3_configgpio(STEP_IN4, OUTPUT);
460	}
461	
462	void board_feeder_init(void)
463	{
464	  feeder_pins_output();
465	  step_coils(0);                       /* coils off at rest: no heat, no hum */
466	  syslog(LOG_ERR, "[feeder] 28BYJ-48 stepper ready (ULN2003 on %d/%d/%d/%d)\n",
467	         STEP_IN1, STEP_IN2, STEP_IN3, STEP_IN4);
468	}
469	
470	/* Rotate the rotor FORWARD by n full steps (ONE direction -> pockets ratchet
471	 * inlet->outlet). Busy-waits STEP_DELAY_US per step, so it MUST run off the UI
472	 * thread -- the app calls board_feeder_dispense from a detached worker (see
473	 * hal/feeder_servo.c). Coils de-energise at the end (no holding current/heat). */
474	static void rotor_step(int n)
475	{
476	  static int phase = 0;
477	  int i;
478	
479	  for (i = 0; i < n; i++)
480	    {
481	      phase = (phase + 1) & 3;
482	      step_coils(k_fullstep[phase]);
483	      up_udelay(STEP_DELAY_US);
484	    }
485	  step_coils(0);
486	}
487	
488	int board_feeder_dispense(int grams)
489	{
490	  int pockets;
491	  int steps;
492	
493	  if (grams <= 0) return -1;
494	
495	  feeder_pins_output();     /* re-claim the coil lines; see the note above */
496	
497	  /* round to the nearest whole pocket; always give at least one */
498	  pockets = (grams + GRAMS_PER_POCKET / 2) / GRAMS_PER_POCKET;
499	  if (pockets < 1) pockets = 1;
500	
501	  steps = pockets * STEP_PER_POCKET;
502	  rotor_step(steps);
503	
504	  syslog(LOG_ERR, "[feeder] dispensed %d pocket(s) ~%dg (%d steps, asked %dg)\n",
505	         pockets, pockets * GRAMS_PER_POCKET, steps, grams);
506	  return 0;
507	}
