510	static int ov5640_rd(struct i2c_master_s *i, uint16_t reg, uint8_t *val)
511	{
512	  struct i2c_msg_s m[2]; uint8_t a[2];
513	  a[0]=(uint8_t)(reg>>8); a[1]=(uint8_t)(reg&0xff);
514	  m[0].frequency=100000; m[0].addr=0x3C; m[0].flags=0;          m[0].buffer=a;   m[0].length=2;

