691	#define GPIO_IN_REG 0x6000403CU
692	static inline int cam_vsync_level(void){ return (rreg(GPIO_IN_REG) >> CAM_VSYNC) & 1; }
693	
694	/* Block until a fresh frame boundary. VSYNC assumed active-high pulse
695	 * (OV5640 default): wait for the pulse (high) then its end (low)=frame start.
696	 * Bounded so a stuck line can't hang boot. */
697	static void cam_wait_vsync(void)
698	{
699	  volatile int i;
700	  for(i=0;i<4000000;i++){ if(cam_vsync_level()) break; }   /* -> high (pulse) */
701	  for(i=0;i<4000000;i++){ if(!cam_vsync_level()) break; }  /* -> low (frame start) */
702	}
703	
704	/* Capture one VSYNC-aligned frame into g_cambuf (internal). */
705	static void cam_capture_once(void)
706	{
707	  /* start camera streaming */
708	  creg(R_CAM_CTRL1, B_CAM_START);
709	  sreg(R_CAM_CTRL1, B_CAM_RESET); creg(R_CAM_CTRL1, B_CAM_RESET);
710	  sreg(R_CAM_CTRL, B_CAM_UPDATE);
711	  sreg(R_CAM_CTRL1, B_CAM_START);
712	  /* align to frame start, then arm the DMA -> one clean aligned frame */
713	  cam_wait_vsync();
714	  sreg(R_CAM_CTRL1, B_CAM_AFIFO_RST); creg(R_CAM_CTRL1, B_CAM_AFIFO_RST);
715	  wreg(R_CAM_INT_CLR, ~0u);
716	  esp32s3_dma_disable(g_camchan, false);   /* clean state before re-arm */
717	  esp32s3_dma_load(g_camdesc, g_camchan, false);
718	  esp32s3_dma_enable(g_camchan, false);
719	  /* wait for the frame-end VSYNC so we read a COMPLETE, single frame (a fixed
720	   * delay races the frame time and gives torn/half frames when the scene moves) */
721	  cam_wait_vsync();
722	  up_mdelay(2);    /* let the DMA flush the frame tail from the AFIFO to PSRAM */
723	  cache_invalidate_addr((uint32_t)(uintptr_t)g_cambuf, CAM_FRAME_BYTES);
724	
725	  /* CAMERA WEDGE FIX: make each capture fully self-contained. Leaving the
726	   * GDMA channel enabled and the LCD_CAM streaming between captures corrupts
727	   * the descriptor/AFIFO state after ~N frames and wedges the whole SoC
728	   * (seen as a console "semaphore timeout"). Stop the RX DMA and halt camera
729	   * streaming after every frame; the next capture re-arms cleanly. */
730	  esp32s3_dma_disable(g_camchan, false);
731	  creg(R_CAM_CTRL1, B_CAM_START);   /* clear START -> stop streaming */
732	}
