757	/* ==========================================================================
758	 * SPI CAPTURE / LOGIC-ANALYZER DIAGNOSTIC MODE
759	 *
760	 * Set SPI_CAPTURE_BUILD to 1 to build a DEDICATED diagnostic image: it does NOT
761	 * run the UI. It bit-bangs the panel init (proven), paints a RED full screen as
762	 * a visible "this build is alive" marker (no console in this mode), then drives
763	 * PURE hardware SPI2 at 1 MHz -- slow enough that a 24 MHz analyzer resolves
764	 * every edge -- looping a full-screen BLUE fill (historically works) and a
765	 * 100x100 BLUE square (the case that fails).
766	 *
767	 * Probe pins (the real SPI pins 1/5/3 are not on the header):
768	 *   GPIO40 = MOSI mirror (FSPID_OUT 103)   -> analyzer CH0
769	 *   GPIO41 = CLK  mirror (FSPICLK_OUT 101)  -> analyzer CH1
770	 *   GPIO42 = DC   mirror                    -> analyzer CH2
771	 *   GPIO47 = TRIG: HIGH during the FAILING partial transaction -> CH3 (trigger)
772	 *   plus analyzer GND -> board GND.
773	 *
774	 * Set back to 0 (or restore the golden board file) to return to the product.
775	 * ========================================================================== */
776	#define SPI_CAPTURE_BUILD 0
777	/* Set to 1 to drive the 4 probe pins as clean, SLOW, DISTINCT square waves
778	 * instead of the SPI test -- a ground-truth to verify the analyzer wiring +
779	 * channel<->pin mapping before trusting any SPI capture. Each pin toggles at
780	 * half the rate of the previous, so a good capture shows 4 nested squares:
781	 *   GPIO40(D0)=fastest ... GPIO47(D3)=slowest. Any channel that reads noise
782	 * instead of a clean square is not actually connected. */
783	#define GPIO_GROUND_TEST  0
784	
785	#if SPI_CAPTURE_BUILD
786	#define PIN_MOSI_MIRROR 40
787	#define PIN_CLK_MIRROR  41
788	#define PIN_DC_MIRROR   42
789	#define PIN_TRIG        47
790	
791	static void cap_cmd(uint8_t c){ uint8_t b=c; spi_idle();
792	  esp32s3_gpiowrite(PIN_DC,false); esp32s3_gpiowrite(PIN_DC_MIRROR,false);
793	  SPI_SNDBLOCK(g_spi,&b,1); }
794	static void cap_dat(uint8_t d){ uint8_t b=d; spi_idle();
795	  esp32s3_gpiowrite(PIN_DC,true);  esp32s3_gpiowrite(PIN_DC_MIRROR,true);
796	  SPI_SNDBLOCK(g_spi,&b,1); }
797	static void cap_window(int x0,int x1,int y0,int y1){
798	  cap_cmd(0x2A);cap_dat(x0>>8);cap_dat(x0&0xff);cap_dat(x1>>8);cap_dat(x1&0xff);
799	  cap_cmd(0x2B);cap_dat(y0>>8);cap_dat(y0&0xff);cap_dat(y1>>8);cap_dat(y1&0xff);
800	  cap_cmd(0x2C); }
801	static void cap_fill(uint8_t hi,uint8_t lo,int width_px,int rows){
802	  int i; for(i=0;i<width_px;i++){ g_swap[i*2]=hi; g_swap[i*2+1]=lo; }
803	  spi_idle(); esp32s3_gpiowrite(PIN_DC,true); esp32s3_gpiowrite(PIN_DC_MIRROR,true);
804	  for(i=0;i<rows;i++){ SPI_SNDBLOCK(g_spi,g_swap,(size_t)width_px*2); } }
