374	/****************************************************************************
375	 * camera capture, counted
376	 *
377	 * The board wedged (console "semaphore timeout") after a long idle on the
378	 * Enroll tab -- the preview grabs a frame every FRAME_INTERVAL_MS forever, so
379	 * minutes of idling = many thousands of captures, and the next Capture died.
380	 * Every capture goes through here so the log tells us the frame number at the
381	 * wedge: a repeatable count => something leaks per-capture; no pattern => it's
382	 * time/temperature/electrical. Do not guess this one again.
383	 ****************************************************************************/
384	
385	static unsigned long g_cap_n;
386	
387	/* ---- background inference worker: shared state -----------------------------
388	 * Declared up here because BOTH the recognize loop and Enroll's Capture hand
389	 * work to the worker. Inference MUST NOT run on the UI task: that task's stack
390	 * is in PSRAM, and running the ESP-NN/TFLM Invoke on a PSRAM stack wedges the
391	 * SoC (console goes dead, "semaphore timeout") -- the same trap the flash model
392	 * loader hit. A pthread's stack is heap/internal RAM, where it runs fine.
393	 * Protocol: 0 idle -> 1 request -> 2 busy -> 3 done -> 0. */
394	static struct velapaw_frame   g_inf_frame;
395	static float                  g_inf_emb[VELAPAW_EMBED_DIM];
396	static struct velapaw_match   g_inf_m;
397	static uint32_t               g_inf_us;
398	static volatile int           g_inf_state;  /* 0 idle,1 request,2 busy,3 done */
399	static volatile int           g_inf_mode;   /* 0 = recognize, 1 = enroll capture */
400	static int                    g_cap_pending;/* an enroll capture is in flight */
401	
402	/* Serialises the two TFLM interpreters (vision embed / KWS classify), which
403	 * now live on two different threads and would otherwise Invoke concurrently.
404	 * Their arenas are separate, so this is not about the arenas -- it is the
405	 * ESP-NN kernels underneath them, which VelaPaw builds with the optimised
406	 * path and which are not documented to be reentrant.  Serialising costs
407	 * nothing we can measure (vision runs at most every RECOG_INTERVAL_MS, voice
408	 * classify is ~90 ms) whereas the failure mode for getting it wrong on this
409	 * board is a dead console with no backtrace.  Capture is deliberately OUTSIDE
