243	/* ---- wall clock -----------------------------------------------------------
244	 * Software CLOCK_REALTIME (no hardware RTC: enabling it killed the USB console,
245	 * so the clock is set by the user each session via Set Clock and starts at a
246	 * sane default). LOCALTIME is off, so derive HH:MM straight from epoch seconds
247	 * and treat that as local time. */
248	static int wall_min(void)          /* minute-of-day, 0..1439 */
249	{
250	  struct timespec ts;
251	  clock_gettime(CLOCK_REALTIME, &ts);
252	  return (int)((ts.tv_sec % 86400) / 60);
253	}
254	static long wall_day(void)         /* day number (for per-day "fed" resets) */
255	{
256	  struct timespec ts;
257	  clock_gettime(CLOCK_REALTIME, &ts);
258	  return (long)(ts.tv_sec / 86400);
259	}
260	/* Board hook: persist the clock into the on-board PCF85063 RTC chip (direct
261	 * I2C in the board file). Weak-ish: returns <0 if the chip isn't there. */
262	extern int board_rtc_settime(time_t t);
263	
264	static void wall_set_min(int minofday)   /* set clock to today at HH:MM */
265	{
266	  struct timespec ts;
267	  clock_gettime(CLOCK_REALTIME, &ts);
268	  if (minofday < 0) minofday += 1440;
269	  minofday %= 1440;
270	  ts.tv_sec  = (ts.tv_sec / 86400) * 86400 + (long)minofday * 60;
271	  ts.tv_nsec = 0;
272	  clock_settime(CLOCK_REALTIME, &ts);
273	  board_rtc_settime(ts.tv_sec);   /* survive reset / power-off */
274	}
