325	/****************************************************************************
326	 * frame display
327	 ****************************************************************************/
328	
329	static void frame_to_565(const struct velapaw_frame *f, uint16_t *dst)
330	{
331	  /* Rotate 90 deg counter-clockwise while converting (the sensor is mounted
332	   * rotated). Square frame (128x128), dims unchanged. dst(dr,dc)=src(dc, W-1-dr). */
333	  int W = f->width, H = f->height;
334	  for (int dr = 0; dr < H; dr++)
335	    for (int dc = 0; dc < W; dc++)
336	      {
337	        int si = (dc * W + (W - 1 - dr)) * 3;
338	        uint8_t r = f->data[si + 0];
339	        uint8_t g = f->data[si + 1];
340	        uint8_t b = f->data[si + 2];
341	        dst[dr * W + dc] = (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
342	      }
343	}
344	
345	/* Thumbnail version: same 90-deg CCW rotation, decimated 2x (128x128 -> 64x64). */
346	static void frame_to_thumb565(const struct velapaw_frame *f, uint16_t *dst)
347	{
348	  int W = f->width;                     /* 128 (square) */
349	  for (int dr = 0; dr < THUMB_H; dr++)
350	    for (int dc = 0; dc < THUMB_W; dc++)
351	      {
352	        int si = ((dc * 2) * W + (W - 1 - dr * 2)) * 3;
353	        uint8_t r = f->data[si + 0];
354	        uint8_t g = f->data[si + 1];
355	        uint8_t b = f->data[si + 2];
356	        dst[dr * THUMB_W + dc] =
357	            (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
358	      }
359	}
360	
361	static void show_frame(const struct velapaw_frame *f)
362	{
363	  frame_to_565(f, g_img565);
364	  if (g_img)
365	    {
366	      lv_obj_invalidate(g_img);
367	    }
368	  if (g_img_r)
369	    {
370	      lv_obj_invalidate(g_img_r);
371	    }
372	}
