372	static void vp_shift_days(int n)
373	{
374	  if (n <= 0)
375	    {
376	      return;
377	    }
378	
379	  if (n > DAYS)
380	    {
381	      n = DAYS;
382	    }
383	
384	  for (int p = 0; p < VELAPAW_MAX_PETS; p++)
385	    {
386	      int d = 0;
387	      for (; d < DAYS - n; d++)
388	        {
389	          g_day_g[p][d] = g_day_g[p][d + n];
390	          g_day_m[p][d] = g_day_m[p][d + n];
391	        }
392	
393	      for (; d < DAYS; d++)
394	        {
395	          g_day_g[p][d] = 0;
396	          g_day_m[p][d] = 0;
397	        }
398	    }
399	}
