/* today_total() does not reconcile, so a day that ended at the daily cap made
 * the feeder refuse every meal of the next one: the 08:00 meal saw
 * yesterday's grams and logged "limit hit" without feeding.  Only a feed or a
 * reboot used to roll the window.  Called by the UI when the day number
 * changes.  UI thread only -- vp_sync_day() is not safe against a second
 * caller.
 */
void velapaw_store_sync_day(void)
{
  long before = g_hist_day;

  vp_sync_day();
  if (g_hist_day != before)
    {
      vp_status_write();
    }
}

