2345	/* ---- background inference worker -----------------------------------------
2346	 * Runs the ~1.3s embed()+match() OFF the UI thread so touch + LVGL stay live
2347	 * while the model runs. Single producer (UI loop) / single consumer (worker),
2348	 * coordinated by g_inf_state: 0 idle -> 1 request -> 2 busy -> 3 done -> 0.
2349	 * The UI pauses camera preview capture while state != 0 so the shared frame
2350	 * buffer the worker reads is never overwritten mid-inference.
2351	 * (State lives near the top of the file -- Capture needs it too.) */
2352	
2353	static void *recog_worker(void *arg)
2354	{
