278	{
279	  struct stat st;
280	  bool fresh;
281	  char when[40];
282	
283	  if (!vp_ensure_dir())
284	    {
285	      return;
286	    }
287	
288	  /* Restart rather than grow without bound. */
289	  fresh = (stat(VP_FEEDLOG, &st) != 0) || (st.st_size > VP_LOG_MAX);
290	
291	  FILE *f = fopen(VP_FEEDLOG, fresh ? "w" : "a");
292	  if (f == NULL)
293	    {
294	      return;
295	    }
296	
297	  if (fresh)
298	    {
299	      fputs("# VelaPaw Feed Log\n\n"
300	            "Most recent feeding events, newest last.\n\n", f);
301	    }
302	
303	  if (ev->ts > VP_TS_SANE)
304	    {
305	      struct tm tmv;
306	      localtime_r(&ev->ts, &tmv);
307	      strftime(when, sizeof(when), "%Y-%m-%d %H:%M", &tmv);
308	    }
309	  else
310	    {
311	      snprintf(when, sizeof(when), "epoch %ld (clock unset)", (long)ev->ts);
312	    }
313	
314	  const struct velapaw_pet *p = velapaw_identity_get(ev->pet_id);
315	
316	  fprintf(f, "- [%s] %s fed %d g (match %.2f, model %s)\n",
317	          when,
