3476	/* Copy an LLM reply into `dst` as one line the LCD can draw.  Replies arrive
3477	 * as markdown with typographic punctuation; the CJK subset font has no glyph
3478	 * for a curly quote or a dash and would leave a blank.  So: drop * # `, fold
3479	 * every run of whitespace into one space, map smart punctuation to ASCII, drop
3480	 * 4-byte UTF-8 (emoji) and malformed bytes, and cut on a whole character with
3481	 * "..." when it does not fit. */
3482	static void ag_clean(char *dst, size_t cap, const char *src)
3483	{
3484	  const unsigned char *s = (const unsigned char *)src;
3485	  size_t n = 0;
3486	  int sp = 0;                          /* a space is owed before the next char */
3487	  int cut = 0;
3488	
3489	  if (cap < 4 || s == NULL)
3490	    {
3491	      if (cap > 0)
3492	        {
3493	          dst[0] = '\0';
3494	        }
3495	
3496	      return;
3497	    }
3498	
3499	  while (*s)
3500	    {
3501	      const char *rep = NULL;          /* ASCII stand-in for this character */
3502	      size_t len = 1;
3503	      unsigned c = s[0];
3504	
3505	      if (c < 0x80)
3506	        {
3507	          if (c == '*' || c == '#' || c == '`')
3508	            {
3509	              s++;
3510	              continue;
3511	            }
3512	
3513	          if (c <= ' ' || c == 0x7f)
3514	            {
3515	              sp = (n > 0);
3516	              s++;
3517	              continue;
3518	            }
3519	        }
3520	      else if ((c & 0xe0) == 0xc0 && (s[1] & 0xc0) == 0x80)
3521	        {
3522	          len = 2;
3523	          if (c == 0xc2 && s[1] == 0xa0)               /* no-break space */
3524	            {
3525	              sp = (n > 0);
3526	              s += 2;
3527	              continue;
3528	            }
3529	        }
3530	      else if ((c & 0xf0) == 0xe0 && (s[1] & 0xc0) == 0x80 &&
3531	               (s[2] & 0xc0) == 0x80)
3532	        {
3533	          len = 3;
3534	          if (c == 0xe2 && s[1] == 0x80)
3535	            {
3536	              switch (s[2])
3537	                {
3538	                  case 0x98: case 0x99: rep = "'";   break;  /* U+2018/9 */
3539	                  case 0x9c: case 0x9d: rep = "\"";  break;  /* U+201C/D */
3540	                  case 0x93: case 0x94: rep = "-";   break;  /* U+2013/4 */
3541	                  case 0xa6:            rep = "..."; break;  /* U+2026   */
3542	                  default:                           break;
3543	                }
3544	            }
3545	        }
3546	      else
3547	        {
3548	          /* emoji or a broken sequence: skip it and its continuation bytes */
3549	
3550	          s++;
3551	          while ((*s & 0xc0) == 0x80)
3552	            {
3553	              s++;
3554	            }
3555	
3556	          continue;
3557	        }
3558	
3559	      size_t olen = rep ? strlen(rep) : len;
3560	
3561	      if (n + (sp ? 1 : 0) + olen > cap - 4)          /* room for "..." + NUL */
3562	        {
3563	          cut = 1;
3564	          break;
3565	        }
3566	
3567	      if (sp)
3568	        {
3569	          dst[n++] = ' ';
3570	          sp = 0;
3571	        }
3572	
3573	      memcpy(dst + n, rep ? rep : (const char *)s, olen);
3574	      n += olen;
3575	      s += len;
3576	    }
3577	
3578	  if (cut)
3579	    {
3580	      memcpy(dst + n, "...", 3);
3581	      n += 3;
3582	    }
3583	
3584	  dst[n] = '\0';
3585	}
