194	static void vp_status_write(void)
195	{
196	  static const char *bcs_txt[] =
197	    {
198	      "under", "ideal", "over"
199	    };
200	
201	  if (!vp_ensure_dir())
202	    {
203	      return;
204	    }
205	
206	  FILE *f = fopen(VP_STATUS, "w");
207	  if (f == NULL)
208	    {
209	      return;
210	    }
211	
212	  fputs("# VelaPaw Feeding Status\n\n", f);
