228	      int b = g_bcs[id];
229	
230	      fprintf(f, "## %s\n", name);
231	      fprintf(f, "- today: %d g in %d meal(s)\n",
232	              velapaw_store_today_total(id), velapaw_store_today_meals(id));
233	      fprintf(f, "- last 7 days: %d g\n", velapaw_store_week_total(id));
234	      fprintf(f, "- baseline (average of prior days): %d g/day\n",
235	              velapaw_store_baseline_g(id));
236	      fprintf(f, "- appetite today: %d%% of baseline\n",
237	              velapaw_store_appetite_pct(id));
238	      fprintf(f, "- body condition: %s\n",
239	              (b >= 0 && b <= 2) ? bcs_txt[b] : "not scored");
240	      fprintf(f, "- owner daily limit: %d g\n", p != NULL ? p->daily_limit_g : 0);
241	      /* The agent has no tool that reads meal times -- it reads this file.
242	       * Publishing them here is what makes a get_meal_schedule tool
243	       * unnecessary, which keeps the tool-schema budget intact.
244	       */
245	
246	      fputs("- scheduled meals:", f);
247	
248	      for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
249	        {
250	          int m = (p != NULL) ? p->meal_min[k] : -1;
251	
252	          if (m < 0)
253	            {
254	              fputs(" off", f);
255	            }
256	          else
257	            {
258	              fprintf(f, " %02d:%02d", m / 60, m % 60);
259	            }
260	        }
261	
262	      fputs("\n", f);
263	
264	      if (velapaw_store_alert_drop(id))
265	        {
266	          fputs("- ALERT: intake on the last completed day was under half "
267	                "the baseline, an early illness sign worth flagging to the "
268	                "owner\n", f);
269	        }
270	
271	      fputs("\n", f);
272	    }
273	
274	  fclose(f);
