531	int velapaw_store_baseline_g(velapaw_pet_id_t id)
532	{
533	  if (!valid(id))
534	    {
535	      return 0;
536	    }
537	  int sum = 0;
538	  for (int d = 0; d < TODAY; d++)
539	    {
540	      sum += g_day_g[id][d];
541	    }
