611	/* Drop a pet's history and shift the rest down. Pet ids are array indices, so
612	 * velapaw_identity_delete() renumbers every later pet -- this keeps the history
613	 * attached to the right animal instead of silently inheriting it. */
614	void velapaw_store_delete(velapaw_pet_id_t id)
615	{
616	  if (!valid(id))
617	    {
618	      return;
619	    }
620	
621	  for (int p = id; p < VELAPAW_MAX_PETS - 1; p++)
622	    {
623	      memcpy(g_day_g[p], g_day_g[p + 1], sizeof(g_day_g[0]));
624	      memcpy(g_day_m[p], g_day_m[p + 1], sizeof(g_day_m[0]));
625	      g_bcs[p] = g_bcs[p + 1];
626	    }
627	
628	  memset(g_day_g[VELAPAW_MAX_PETS - 1], 0, sizeof(g_day_g[0]));
629	  memset(g_day_m[VELAPAW_MAX_PETS - 1], 0, sizeof(g_day_m[0]));
630	  g_bcs[VELAPAW_MAX_PETS - 1] = -1;
