661	/* today_total() does not reconcile, so a day that ended at the daily cap made
662	 * the feeder refuse every meal of the next one: the first meal saw
663	 * yesterday's grams, was marked "limit hit" and nothing was fed -- and with
664	 * no feed, nothing ever rolled the window.  Only a feed or a reboot did.
665	 * Called by the UI when the day number changes.  UI thread only --
666	 * vp_sync_day() is not safe against a second caller.
667	 */
668	void velapaw_store_sync_day(void)
669	{
670	  long before = g_hist_day;
671	
672	  vp_sync_day();
673	  if (g_hist_day != before)
674	    {
675	      vp_status_write();
676	    }
677	}
