818	 * appetite / alert  (relative to each pet's DAILY LIMIT = the ration the
819	 * owner set, not a rolling average)
820	 ****************************************************************************/
821	
822	/* % of today's ration eaten: today / daily_limit (0..100, since feeding stops
823	 * at the limit). 100% = ate its full daily allowance. */
824	static int pet_appetite_pct(velapaw_pet_id_t id, const struct velapaw_pet *p)
825	{
826	  int today = velapaw_store_today_total(id);
827	  int pct = (p->daily_limit_g > 0) ? today * 100 / p->daily_limit_g : 100;
828	  return (pct > 100) ? 100 : pct;   /* limit is a cap: never over 100% */
829	}
830	
831	/* appetite-drop alert: the last completed day was under half the daily limit. */
832	static int pet_alert_drop(velapaw_pet_id_t id, const struct velapaw_pet *p)
833	{
834	  int yesterday = velapaw_store_day_total(id, 1);
835	  return (p->daily_limit_g > 0 && yesterday * 2 < p->daily_limit_g) ? 1 : 0;
836	}
