877	static void do_capture(void)
878	{
879	  if (g_nsamp >= MAX_SHOTS)
880	    {
881	      return;
882	    }
883	  if (g_inf_state != 0 || g_cap_pending)
884	    {
885	      return;                       /* an inference is already in flight */
886	    }
887	
888	  /* Grab the frame here (cheap, ~ms), but hand the INFERENCE to the worker.
889	   * Running embed() inline on this task wedged the SoC -- see the note on the
890	   * worker state above. The loop picks the result up when g_inf_state == 3. */
891	  cam_grab(&g_inf_frame);
892	  g_inf_mode    = 1;                /* enroll capture: embed, don't match */
893	  g_cap_pending = 1;
894	  g_inf_state   = 1;                /* -> worker */
895	  lv_label_set_text(g_sample_lbl, T(S_CAPTURING));
896	}
