45	int velapaw_camera_get_frame(struct velapaw_frame *frame)
46	{
47	  uint8_t *buf = NULL;
48	  int w = 0, h = 0;
49	
50	  if (frame == NULL)
51	    {
52	      return -1;
53	    }
54	
55	  if (board_ov5640_capture(&buf, &w, &h) != 0 || buf == NULL || w <= 0 || h <= 0)
56	    {
57	      /* capture failed: keep the previous frame (or black on first call) */
58	    }
59	  else
60	    {
61	      for (int y = 0; y < VELAPAW_FRAME_H; y++)
62	        {
63	          /* 90 deg CW correction: screen row y walks the source's columns */
64	          int dy = y * w / VELAPAW_FRAME_H;
65	          int sx = dy;
66	          for (int x = 0; x < VELAPAW_FRAME_W; x++)
67	            {
68	              /* selfie mirror applied on the corrected (post-rotation) x axis */
69	              int mox = (VELAPAW_FRAME_W - 1) - x;
70	              int dx = mox * h / VELAPAW_FRAME_W;
71	              int sy = (h - 1) - dx;
72	              const uint8_t *p = buf + ((size_t)sy * w + sx) * 2;
73	
74	              /* RGB565, big-endian byte order in the capture buffer */
75	              uint16_t px = (uint16_t)((p[0] << 8) | p[1]);
76	              uint8_t r = (px >> 11) & 0x1f;
77	              uint8_t g = (px >> 5)  & 0x3f;
78	              uint8_t b =  px        & 0x1f;
79	
80	              int o = (y * VELAPAW_FRAME_W + x) * 3;
81	              g_framebuf[o + 0] = (uint8_t)((r << 3) | (r >> 2));
82	              g_framebuf[o + 1] = (uint8_t)((g << 2) | (g >> 4));
83	              g_framebuf[o + 2] = (uint8_t)((b << 3) | (b >> 2));
84	            }
85	        }
86	    }
87	
88	  frame->data     = g_framebuf;
89	  frame->width    = VELAPAW_FRAME_W;
90	  frame->height   = VELAPAW_FRAME_H;
91	  frame->channels = VELAPAW_FRAME_C;
92	  return 0;
93	}
