1	/****************************************************************************
2	 * VelaPaw - in-memory store backend (emulator) + feeding-behavior analytics
3	 *
4	 * Keeps a rolling 7-day history of grams + meal counts per pet (index
5	 * DAYS-1 == today). Powers daily/weekly intake, meal frequency, appetite
6	 * baseline/trend, and the sudden-appetite-drop alert. Replace with a
7	 * persistent backend (apps/system/settings or littlefs) on hardware so
8	 * history survives reboots.
9	 ****************************************************************************/
10	
11	#include <stdio.h>
12	#include <string.h>
13	#include <stdbool.h>
14	#include <stdint.h>
15	#include <errno.h>
16	#include <fcntl.h>
17	#include <time.h>
18	#include <unistd.h>
19	#include <sys/stat.h>
20	#include "store/store.h"
21	#include "identity/identity.h"
22	
23	#define DAYS VELAPAW_HIST_DAYS
24	#define TODAY (DAYS - 1)
25	
26	static int g_day_g[VELAPAW_MAX_PETS][DAYS];      /* grams per day */
27	static int g_day_m[VELAPAW_MAX_PETS][DAYS];      /* meals per day */
28	static int g_bcs[VELAPAW_MAX_PETS];              /* last BCS: 0/1/2, -1 none */
29	
30	/* Civil day number (see vp_days_from_civil) that owns slot TODAY, or -1
31	 * when it is not known yet: an unset clock, or a pre-VP02 history file.
32	 */
33	static long g_hist_day = -1;
34	
35	static int valid(velapaw_pet_id_t id)
36	{
37	  return id >= 0 && id < VELAPAW_MAX_PETS;
38	}
39	
40	/****************************************************************************
41	 * Agent-readable persistence
42	 *
43	 * The on-device ai_agent needs real feeding data to summarise, and its
44	 * read_file tool is sandboxed to the agent data dir, so everything lands
45	 * under <agent data dir>/velapaw/:
46	 *
47	 *   history.bin  compact machine copy of the rolling window, reloaded at
48	 *                init so the history survives a reboot
49	 *   status.md    the digest a skill reads: per-pet totals, baseline,
50	 *                appetite %, body condition, drop alert
51	 *   feed_log.md  append-only recent events, size-capped
52	 *
53	 * Doing this from the velapaw task directly is safe: since the ai_agent
54	 * merge every task stack is carved from the XTENSA_IMEM heap and lives in
55	 * internal SRAM (measured: velapaw StackBase 0x3fcabc98), so a littlefs
56	 * write no longer runs with the stack sitting behind the disabled flash
57	 * cache -- the freeze that identity.c's worker thread exists to dodge.
58	 * If a stack ever moves back to PSRAM (0x3c......), these calls must move
59	 * onto that worker-thread pattern too.
60	 *
61	 * Every write is best-effort.  If /data is not mounted the calls fail
62	 * quietly and the in-memory analytics behave exactly as they did before.
63	 ****************************************************************************/
64	
65	#ifdef CONFIG_EXAMPLES_AI_AGENT_VELA_DATA_DIR
66	#  define VP_AGENT_DIR CONFIG_EXAMPLES_AI_AGENT_VELA_DATA_DIR
67	#else
68	#  define VP_AGENT_DIR "/data/ai_agent"
69	#endif
70	
71	#define VP_DIR      VP_AGENT_DIR "/velapaw"
72	#define VP_HISTORY  VP_DIR "/history.bin"
73	#define VP_STATUS   VP_DIR "/status.md"
74	#define VP_FEEDLOG  VP_DIR "/feed_log.md"
75	
76	/* read_file tops out at 32 KB and the /data partition is under 1 MB. */
77	#define VP_LOG_MAX  8192
78	#define VP_MAGIC_V1 0x56503031u        /* "VP01" -- before the day stamp */
79	#define VP_MAGIC    0x56503032u        /* "VP02" */
80	
81	/* Below this the realtime clock is clearly unset; printing a 1970 date
82	 * would mislead the model, so the raw epoch is logged instead. */
83	#define VP_TS_SANE  1600000000
84	
85	static bool g_fs_ready;
86	
87	static bool vp_ensure_dir(void)
88	{
89	  if (g_fs_ready)
90	    {
91	      return true;
92	    }
93	
94	  if (mkdir(VP_AGENT_DIR, 0755) != 0 && errno != EEXIST)
95	    {
96	      return false;
97	    }
98	
99	  if (mkdir(VP_DIR, 0755) != 0 && errno != EEXIST)
100	    {
101	      return false;
102	    }
103	
104	  g_fs_ready = true;
105	  return true;
106	}
