108	static void vp_history_save(void)
109	{
110	  if (!vp_ensure_dir())
111	    {
112	      return;
113	    }
114	
115	  FILE *f = fopen(VP_HISTORY, "wb");
116	  if (f == NULL)
117	    {
118	      return;
119	    }
120	
121	  /* hdr[3] is the civil day owning slot TODAY, -1 when unknown. */
122	  uint32_t hdr[4] =
123	    {
124	      VP_MAGIC, VELAPAW_MAX_PETS, DAYS, (uint32_t)(int32_t)g_hist_day
125	    };
126	
127	  if (fwrite(hdr, sizeof(hdr), 1, f) == 1)
128	    {
129	      fwrite(g_day_g, sizeof(g_day_g), 1, f);
130	      fwrite(g_day_m, sizeof(g_day_m), 1, f);
131	      fwrite(g_bcs,   sizeof(g_bcs),   1, f);
132	    }
133	
134	  fclose(f);
135	}
136	
137	static void vp_history_load(void)
138	{
139	  FILE *f = fopen(VP_HISTORY, "rb");
140	  if (f == NULL)
141	    {
142	      return;
143	    }
144	
145	  uint32_t hdr[4];
146	  bool ok;
147	
148	  /* Geometry is part of the format: a rebuild that changes MAX_PETS or the
149	   * window length invalidates the file instead of misreading it. */
150	  ok = fread(hdr, sizeof(uint32_t), 3, f) == 3
151	       && hdr[1] == VELAPAW_MAX_PETS
152	       && hdr[2] == DAYS;
153	
154	  if (ok && hdr[0] == VP_MAGIC)
155	    {
156	      ok = fread(&hdr[3], sizeof(uint32_t), 1, f) == 1;
157	      g_hist_day = ok ? (long)(int32_t)hdr[3] : -1;
158	    }
159	  else if (ok && hdr[0] == VP_MAGIC_V1)
160	    {
161	      /* Pre-day-stamp file: the arrays are still good, the day simply was
162	       * never recorded.  vp_sync_day() adopts today without shifting,
163	       * rather than guessing and throwing real days away. */
164	      g_hist_day = -1;
165	    }
166	  else
167	    {
168	      ok = false;
169	    }
170	
171	  if (ok)
172	    {
173	      if (fread(g_day_g, sizeof(g_day_g), 1, f) != 1
174	          || fread(g_day_m, sizeof(g_day_m), 1, f) != 1
175	          || fread(g_bcs, sizeof(g_bcs), 1, f) != 1)
176	        {
177	          /* Short or corrupt: a clean slate beats a half-loaded history. */
178	          memset(g_day_g, 0, sizeof(g_day_g));
179	          memset(g_day_m, 0, sizeof(g_day_m));
180	          for (int i = 0; i < VELAPAW_MAX_PETS; i++)
181	            {
182	              g_bcs[i] = -1;
183	            }
184	
185	          printf("velapaw/store: %s corrupt, history reset\n", VP_HISTORY);
186	        }
187	      else
188	        {
189	          printf("velapaw/store: history restored from %s\n", VP_HISTORY);
190	        }
191	    }
192	
193	  fclose(f);
194	}
