403	/* Reconcile the window with the wall clock.  Safe on every path that
404	 * touches the history -- it is a no-op within a single day.
405	 */
406	static void vp_sync_day(void)
407	{
408	  long today = vp_today_num();
409	
410	  if (today < 0)
411	    {
412	      return;              /* clock unusable -- leave the window alone */
413	    }
414	
415	  if (g_hist_day < 0)
416	    {
417	      /* First run, or a VP01 file: the data in the window is real, we just
418	       * never knew which day it belonged to.  Adopt today, do not shift.
419	       */
420	      g_hist_day = today;
421	      vp_history_save();
422	      return;
423	    }
424	
425	  if (today <= g_hist_day)
426	    {
427	      /* Same day, or the clock jumped backwards -- which the build-date
428	       * boot anchor does on every cold start.  Never shift backwards: it
429	       * would drop real days off the front and zero slots that hold data.
430	       */
431	      return;
432	    }
433	
434	  vp_shift_days((int)(today - g_hist_day));
435	  g_hist_day = today;
436	  vp_history_save();
437	}
