439	int velapaw_store_init(void)
440	{
441	  memset(g_day_g, 0, sizeof(g_day_g));
442	  memset(g_day_m, 0, sizeof(g_day_m));
443	  for (int i = 0; i < VELAPAW_MAX_PETS; i++)
444	    {
445	      g_bcs[i] = -1;
446	    }
447	
448	  vp_history_load();
449	
450	  /* A board that has been off -- or simply running -- across midnight has
451	   * to shift before it reports anything.
452	   */
453	  vp_sync_day();
454	
455	  /* Write the digest at startup too.  Without this, status.md does not exist
456	   * until the next feed, enroll or BCS update, so a freshly booted board
457	   * gives the agent's skill nothing to read. */
458	  vp_status_write();
459	  return 0;
460	}
