462	int velapaw_store_log_feeding(const struct velapaw_feed_event *ev)
463	{
464	  if (ev == NULL || !valid(ev->pet_id))
465	    {
466	      return -1;
467	    }
468	
469	  /* Bucket the event in the right day even if the board has been up since
470	   * before midnight.
471	   */
472	  vp_sync_day();
473	
474	  g_day_g[ev->pet_id][TODAY] += ev->grams;
475	  g_day_m[ev->pet_id][TODAY] += 1;
476	
477	  /* Save first, print last.  The console can block for good when the host
478	   * stops reading it, and a meal that was dispensed but never saved is fed
479	   * again after the reset that follows. */
480	
481	  vp_feedlog_append(ev);
482	  vp_persist();
483	
484	  printf("    [store] event pet=%d grams=%d score=%.2f model=%s\n",
485	         ev->pet_id, ev->grams, ev->score, ev->model ? ev->model : "?");
486	  return 0;
487	}
