412	 * nothing we can measure (vision runs at most every RECOG_INTERVAL_MS, voice
413	 * classify is ~90 ms) whereas the failure mode for getting it wrong on this
414	 * board is a dead console with no backtrace.  Capture is deliberately OUTSIDE
415	 * the lock: the 2 s mic read must overlap with vision, not block it. */
416	static pthread_mutex_t        g_tflm_lock = PTHREAD_MUTEX_INITIALIZER;
417	
418	/****************************************************************************
419	 * staying up: console, health log, stall monitor
420	 *
421	 * The console is CDC-ACM with a 193-byte TX buffer.  When the host stops
422	 * reading it -- PuTTY closed, the port lost, the PC asleep -- the buffer fills
423	 * and the next blocking writer (the agent logs through syslog) waits inside
424	 * the serial driver holding its TX lock.  Every later console write, on any
425	 * thread, queues behind that lock.  The O_NONBLOCK set in velapaw_ui_run
426	 * (which is what keeps a board with no PC at all running) does not help
427	 * here: the lock is taken before the flag is looked at.  A board left running
428	 * froze with nothing on screen to say why.  uprintf() asks the driver for the free
429	 * space first (FIONSPACE takes only a spinlock) and drops the line when the
430	 * buffer stays full.  It writes the fd directly: stdio's FILE lock is shared
431	 * by every thread of the task, and a thread stuck in printf holds it.  Prints
432	 * inside the feeder, TFLM and identity modules are not gated.
433	 *
434	 * What has to survive goes to flash instead: health.log in the velapaw data
435	 * dir gets a line at boot, every 10 minutes and at a stall.
436	 *
437	 * The stall monitor resets the board when the UI loop has not come round for
438	 * STALL_UI_MS, or the inference worker has been inside one request for
439	 * STALL_INF_MS.  It does no I/O and takes no lock, so what wedged the others
440	 * cannot wedge it; the note thread writes the STALL line and the monitor
441	 * waits up to STALL_NOTE_MS for it.  Meals are marked fed before the motor
442	 * turns (fed_save), so the reset cannot serve one twice.  A CPU stuck with
443	 * interrupts off is not covered: this build has no hardware watchdog.
444	 ****************************************************************************/
445	
446	#define CON_TRIES       5         /* FIONSPACE polls before a line is dropped */
447	#define CON_RETRY_MS    10
448	#define CON_CHUNK       96        /* longer lines go out in pieces */
449	#define STALL_UI_MS     120000
450	#define STALL_INF_MS    60000     /* one embed takes ~1.3 s */
451	#define STALL_NOTE_MS   3000
452	#define HEALTH_MS       600000
453	#define CAP_SLOW_MS     400
454	
455	extern void up_systemreset(void);
456	extern int  esp32s3_reset_reasons(int cpu);    /* returns soc_reset_reason_t */
457	
458	static volatile unsigned long g_con_drop;      /* console lines dropped */
459	static volatile long          g_ui_beat;       /* UI loop: last time round */
460	static const char *volatile   g_ui_at = "init";/* ...and what it is doing */
461	static volatile uint32_t      g_ui_tab;
462	static volatile long          g_inf_beat;      /* worker; 0 = never ran */
463	static volatile unsigned long g_inf_n;         /* embeds finished */
464	static volatile unsigned long g_rec_hit;       /* Recognize: pet handled */
465	static volatile unsigned long g_rec_miss;      /* ...gave up, nobody known */
466	static volatile long          g_cap_max;       /* slowest grab this period */
467	static volatile unsigned long g_cap_slow;      /* grabs over CAP_SLOW_MS */
468	static volatile unsigned long g_cap_same;      /* frame equal to the last */
469	static volatile unsigned long g_cap_err;       /* the HAL said it failed */
470	static volatile int           g_stall;         /* 1 UI, 2 worker */
471	static volatile long          g_stall_age;     /* s since its last beat */
472	static const char *volatile   g_stall_at;
473	static volatile int           g_stall_noted;
