478	/* Room for `need` bytes in the console TX buffer, waiting up to CON_TRIES x
479	 * CON_RETRY_MS for the host to drain it.  1 when the driver cannot tell. */
480	static int con_ok(int need)
481	{
482	#ifdef FIONSPACE
483	  for (int i = 0; i < CON_TRIES; i++)
484	    {
485	      int room;
486	
487	      if (ioctl(STDOUT_FILENO, FIONSPACE, (unsigned long)(uintptr_t)&room) < 0
488	          || room >= need)
489	        {
490	          return 1;
491	        }
492	
493	      usleep(CON_RETRY_MS * 1000);
494	    }
495	
496	  return 0;
497	#else
498	  (void)need;
499	  return 1;
500	#endif
501	}
