503	/* printf for the console that drops the line rather than block. */
504	static void uprintf(const char *fmt, ...) __attribute__((format(printf, 1, 2)));
505	static void uprintf(const char *fmt, ...)
506	{
507	  char line[200];
508	  va_list ap;
509	  int n;
510	  int off = 0;
511	
512	  va_start(ap, fmt);
513	  n = vsnprintf(line, sizeof(line), fmt, ap);
514	  va_end(ap);
515	  if (n > (int)sizeof(line) - 1)
516	    {
517	      n = sizeof(line) - 1;
518	    }
519	
520	  while (off < n)
521	    {
522	      int len = n - off < CON_CHUNK ? n - off : CON_CHUNK;
523	      ssize_t w;
524	
525	      if (!con_ok(len))
526	        {
527	          g_con_drop++;
528	          return;
529	        }
530	
531	      w = write(STDOUT_FILENO, line + off, len);
532	      if (w <= 0)
533	        {
534	          return;
535	        }
536	
537	      off += w;
538	    }
539	}
