541	/* Wall time, uptime, tab; camera grabs, slowest this period, slow, repeated,
542	 * failed; embeds, pets handled, gave up, worker state; console lines dropped.
543	 * No heap figure: LVGL allocates from the system heap here (CLIB malloc, so
544	 * lv_mem_monitor() reports nothing), and walking that heap is what free and
545	 * mallinfo do -- they hang this board. */
546	static void health_fmt(char *buf, size_t size)
547	{
548	  int m = wall_min();
549	
550	  snprintf(buf, size,
551	           "%02d:%02d up %ldm tab %lu cap %lu max %ldms slow %lu same %lu "
552	           "err %lu embed %lu hit %lu miss %lu inf %d drop %lu",
553	           m / 60, m % 60, mono_ms() / 60000, (unsigned long)g_ui_tab,
554	           g_cap_n, g_cap_max, g_cap_slow, g_cap_same, g_cap_err,
555	           g_inf_n, g_rec_hit, g_rec_miss, g_inf_state, g_con_drop);
556	}
