565	static void *stall_monitor(void *arg)
566	{
567	  (void)arg;
568	  for (;;)
569	    {
570	      long now;
571	      long ui;
572	      long inf;
573	      int  kind;
574	
575	      sleep(5);
576	      now  = mono_ms();
577	      ui   = now - g_ui_beat;
578	      inf  = g_inf_beat != 0 ? now - g_inf_beat : 0;
579	      kind = ui > STALL_UI_MS ? 1 : inf > STALL_INF_MS ? 2 : 0;
580	      if (kind == 0)
581	        {
582	          continue;
583	        }
584	
585	      g_stall_age = (kind == 1 ? ui : inf) / 1000;
586	      g_stall_at  = g_ui_at;
587	      g_stall     = kind;
588	      for (int i = 0; i < STALL_NOTE_MS / 100 && !g_stall_noted; i++)
589	        {
590	          usleep(100000);
591	        }
592	
593	      up_systemreset();
594	    }
595	
596	  return NULL;
597	}
