599	/* The boot line, the 10-minute line, and the STALL line for the monitor. */
600	static void *stall_note(void *arg)
601	{
602	  char line[200];
603	  long next = mono_ms() + HEALTH_MS;
604	  int  m = wall_min();
605	  int  n;
606	
607	  (void)arg;
608	  snprintf(line, sizeof(line), "%02d:%02d boot rst 0x%02x",
609	           m / 60, m % 60, (unsigned)g_boot_rr);
610	  health_note(line);
611	  for (;;)
612	    {
613	      usleep(250000);
614	      if (g_stall != 0)
615	        {
616	          n = snprintf(line, sizeof(line), "STALL %s at %s %lds | ",
617	                       g_stall == 1 ? "ui" : "worker", g_stall_at,
618	                       g_stall_age);
619	          if (n > 0 && n < (int)sizeof(line))
620	            {
621	              health_fmt(line + n, sizeof(line) - n);
622	            }
623	
624	          health_note(line);
625	          usleep(200000);                 /* let the console line out */
626	          g_stall_noted = 1;
627	          for (;;)
628	            {
629	              sleep(60);
630	            }
631	        }
632	
633	      if (mono_ms() - next >= 0)
634	        {
635	          next += HEALTH_MS;
636	          health_fmt(line, sizeof(line));
637	          health_note(line);
638	          g_cap_max = 0;
639	        }
640	    }
641	
642	  return NULL;
643	}
