645	/* Started just before the UI loop, not earlier: a boot that wedges would
646	 * otherwise turn into a reset loop that floods health.log. */
647	static void stall_start(void)
648	{
649	  struct sched_param sp;
650	  pthread_attr_t attr;
651	  pthread_t tid;
652	  int prio = 100;
653	  int pmax = sched_get_priority_max(SCHED_FIFO);
654	  int ok = 0;
655	
656	  if (sched_getparam(0, &sp) == 0)
657	    {
658	      prio = sp.sched_priority;
659	    }
660	
661	  if (pmax > 10 && prio > pmax - 10)
662	    {
663	      prio = pmax - 10;
664	    }
665	
666	  pthread_attr_init(&attr);
667	  pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
668	
669	  pthread_attr_setstacksize(&attr, 2048);
670	  sp.sched_priority = prio + 10;
671	  pthread_attr_setschedparam(&attr, &sp);
672	  if (pthread_create(&tid, &attr, stall_monitor, NULL) == 0)
673	    {
674	      pthread_detach(tid);
675	      ok++;
676	    }
677	
678	  pthread_attr_setstacksize(&attr, 6144);
679	  sp.sched_priority = prio + 5;
680	  pthread_attr_setschedparam(&attr, &sp);
681	  if (pthread_create(&tid, &attr, stall_note, NULL) == 0)
682	    {
683	      pthread_detach(tid);
684	      ok++;
685	    }
686	
687	  pthread_attr_destroy(&attr);
688	  uprintf("velapaw: stall monitor %s\n", ok == 2 ? "armed" : "NOT started");
689	}
