691	/****************************************************************************
692	 * meal state that survives a reset, and when to look again
693	 *
694	 * Which meals were eaten today, when and how much, and which the owner
695	 * skipped, lived only in RAM: every reset -- now including the stall
696	 * monitor's -- served the day's meals again.  fed.bin keeps them.  A skip
697	 * counts only for the day it was set.
698	 ****************************************************************************/
699	
700	#define FEED_GAP_MIN       20     /* minutes between two meals of one pet */
701	#define REARM_HIT_MS       30000  /* after a pet was handled */
702	#define REARM_MISS_MS      3000   /* after nobody known: doubles... */
703	#define REARM_MISS_MAX_MS  20000  /* ...up to this */
704	#define MEAL_POLL_MS       60000  /* one look a minute while a meal is due */
705	#define MEAL_POLL_WIN_MIN  30     /* ...for its first 30 minutes */
706	#define SIG_CELL_DIFF      20     /* scene_moved(): a cell changed */
707	#define SIG_MIN_CELLS      2      /* ...this many of the 16 */
708	#define SIG_SHIFT_MAX      48     /* ...or the whole picture (a light) */
709	#define FED_MAGIC          0x56504631u   /* "VPF1" */
710	
711	struct fed_state
712	{
713	  uint32_t magic;
714	  uint32_t size;                  /* a geometry change voids the file */
715	  long     day;                   /* wall_day() at save */
716	  long     fed_day[VELAPAW_MAX_PETS][VELAPAW_MAX_MEALS];
717	  int      fed_min[VELAPAW_MAX_PETS][VELAPAW_MAX_MEALS];
718	  int      fed_g[VELAPAW_MAX_PETS][VELAPAW_MAX_MEALS];
719	  uint8_t  skipped[VELAPAW_MAX_PETS][VELAPAW_MAX_MEALS];
720	};
