722	/* After every change to the four arrays.  UI thread only. */
723	static void fed_save(void)
724	{
725	  struct fed_state s;
726	
727	  memset(&s, 0, sizeof(s));
728	  s.magic = FED_MAGIC;
729	  s.size  = sizeof(s);
730	  s.day   = wall_day();
731	  memcpy(s.fed_day, g_meal_fed_day, sizeof(s.fed_day));
732	  memcpy(s.fed_min, g_meal_fed_min, sizeof(s.fed_min));
733	  memcpy(s.fed_g,   g_meal_fed_g,   sizeof(s.fed_g));
734	  memcpy(s.skipped, g_meal_skipped, sizeof(s.skipped));
735	  if (velapaw_store_put("fed.bin", &s, sizeof(s)) < 0)
