741	static void fed_load(void)
742	{
743	  struct fed_state s;
744	
745	  if (velapaw_store_get("fed.bin", &s, sizeof(s)) != (int)sizeof(s) ||
746	      s.magic != FED_MAGIC || s.size != sizeof(s))
747	    {
748	      return;
