752	  memcpy(g_meal_fed_min, s.fed_min, sizeof(g_meal_fed_min));
753	  memcpy(g_meal_fed_g,   s.fed_g,   sizeof(g_meal_fed_g));
754	  if (s.day == wall_day())
755	    {
