762	/* Minutes until this pet may eat again, 0 = now.  Two meals can be due at
763	 * once (one was missed, or after a reset), and now that recognition wakes by
764	 * itself the second followed the first within seconds.  g_last_fed was meant
765	 * to space them, but nothing ever read it. */
766	static int feed_wait_min(int id, long today, int nowm)
767	{
768	  int wait_min = 0;
769	
770	  for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
771	    {
772	      int ago = nowm - g_meal_fed_min[id][k];
773	
774	      if (g_meal_fed_day[id][k] == today && g_meal_fed_g[id][k] > 0 &&
775	          ago >= 0 && ago < FEED_GAP_MIN && FEED_GAP_MIN - ago > wait_min)
776	        {
777	          wait_min = FEED_GAP_MIN - ago;
778	        }
779	    }
780	
781	  return wait_min;
782	}
