784	/* A meal reached its time in the last MEAL_POLL_WIN_MIN minutes and is
785	 * neither eaten nor skipped: worth a look at the bowl even when the picture
786	 * has not changed.  Not all day -- a pet that never came must not keep the
787	 * camera and the model busy until midnight.  UI thread only. */
788	static int meal_window_open(void)
789	{
790	  long today = wall_day();
791	  int  nowm  = wall_min();
792	  int  n     = velapaw_identity_count();
793	
794	  for (int i = 0; i < n && i < VELAPAW_MAX_PETS; i++)
795	    {
796	      const struct velapaw_pet *p = velapaw_identity_get(i);
797	
798	      for (int k = 0; p != NULL && k < VELAPAW_MAX_MEALS; k++)
799	        {
800	          int since = nowm - p->meal_min[k];
801	
802	          if (p->meal_min[k] >= 0 && since >= 0 &&
803	              since < MEAL_POLL_WIN_MIN &&
804	              g_meal_fed_day[i][k] != today && !g_meal_skipped[i][k])
805	            {
806	              return 1;
807	            }
808	        }
809	    }
810	
811	  return 0;
812	}
