814	/* Mean brightness of a 4x4 grid, from every 4th pixel each way (~1000
815	 * reads): cheap enough for each preview frame.  -1 if there is no picture. */
816	static int scene_sig(const struct velapaw_frame *f, uint8_t sig[16])
817	{
818	  int cw;
819	  int chh;
820	
821	  if (f == NULL || f->data == NULL || f->channels < 1 ||
822	      f->width < 16 || f->height < 16)
823	    {
824	      return -1;
825	    }
826	
827	  cw  = f->width / 4;
828	  chh = f->height / 4;
829	  for (int cy = 0; cy < 4; cy++)
830	    {
831	      for (int cx = 0; cx < 4; cx++)
832	        {
833	          uint32_t sum = 0;
834	          uint32_t cnt = 0;
835	
836	          for (int y = cy * chh; y < (cy + 1) * chh; y += 4)
837	            {
838	              const uint8_t *row = f->data +
839	                                   (size_t)y * f->width * f->channels;
840	
841	              for (int x = cx * cw; x < (cx + 1) * cw; x += 4)
842	                {
843	                  const uint8_t *px = row + (size_t)x * f->channels;
844	
845	                  sum += f->channels >= 3 ?
846	                         (77u * px[0] + 150u * px[1] + 29u * px[2]) >> 8 :
847	                         px[0];
848	                  cnt++;
849	                }
850	            }
851	
852	          sig[cy * 4 + cx] = (uint8_t)(cnt != 0 ? sum / cnt : 0);
853	        }
854	    }
855	
856	  return 0;
857	}
