859	/* Something moved: SIG_MIN_CELLS cells changed beyond the shift of the whole
860	 * picture, or the whole picture shifted a lot.  Sensor noise and exposure
861	 * drift stay under both. */
862	static int scene_moved(const uint8_t ref[16], const uint8_t sig[16])
863	{
864	  int shift = 0;
865	  int cells = 0;
866	
867	  for (int i = 0; i < 16; i++)
868	    {
869	      shift += sig[i] - ref[i];
870	    }
871	
872	  shift /= 16;
873	  if (shift > SIG_SHIFT_MAX || shift < -SIG_SHIFT_MAX)
874	    {
875	      return 1;
876	    }
877	
878	  for (int i = 0; i < 16; i++)
879	    {
880	      int dv = sig[i] - ref[i] - shift;
881	
882	      if (dv > SIG_CELL_DIFF || dv < -SIG_CELL_DIFF)
883	        {
884	          cells++;
885	        }
886	    }
887	
888	  return cells >= SIG_MIN_CELLS;
889	}
