750	int velapaw_store_put(const char *name, const void *buf, size_t len)
751	{
752	  char path[96];
753	  ssize_t n;
754	  int fd;
755	
756	  if (name == NULL || buf == NULL || !vp_ensure_dir() ||
757	      vp_path(path, sizeof(path), name) < 0)
758	    {
759	      return -1;
760	    }
761	
762	  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
763	  if (fd < 0)
764	    {
765	      return -1;
766	    }
767	
768	  n = write(fd, buf, len);
769	  if (close(fd) < 0)
770	    {
771	      return -1;
772	    }
773	
774	  return n == (ssize_t)len ? 0 : -1;
775	}
