777	int velapaw_store_get(const char *name, void *buf, size_t len)
778	{
779	  char path[96];
780	  ssize_t n;
781	  int fd;
782	
783	  if (name == NULL || buf == NULL || vp_path(path, sizeof(path), name) < 0)
784	    {
785	      return -1;
786	    }
787	
788	  fd = open(path, O_RDONLY);
789	  if (fd < 0)
790	    {
791	      return -1;
792	    }
793	
794	  n = read(fd, buf, len);
795	  close(fd);
796	  return n < 0 ? -1 : (int)n;
797	}
