799	void velapaw_store_log_health(const char *line)
800	{
801	  struct stat st;
802	  int fd;
803	
804	  if (line == NULL || !vp_ensure_dir())
805	    {
806	      return;
807	    }
808	
809	  /* unlink first: whether rename() replaces an existing target is up to
810	   * the filesystem, and this must not depend on it. */
811	
812	  if (stat(VP_HEALTH, &st) == 0 && st.st_size >= VP_HEALTH_MAX)
813	    {
814	      unlink(VP_HEALTH_OLD);
815	      rename(VP_HEALTH, VP_HEALTH_OLD);
816	    }
817	
818	  fd = open(VP_HEALTH, O_WRONLY | O_CREAT | O_APPEND, 0644);
819	  if (fd < 0)
820	    {
821	      return;
822	    }
823	
824	  write(fd, line, strlen(line));
825	  write(fd, "\n", 1);
826	  close(fd);
827	}
