1290	/* The HAL returns 0 even when a capture fails and leaves the last good
1291	 * picture in the buffer, so a dead camera looks like a frozen screen.  Count
1292	 * what it does report, the slow grabs, and frames identical to the one
1293	 * before, for the health line. */
1294	static void cam_grab(struct velapaw_frame *f)
1295	{
1296	  static uint32_t last;
1297	  long t0 = mono_ms();
1298	  long ms;
1299	
1300	  g_ui_at = "cam";
1301	  if (velapaw_camera_get_frame(f) != 0)
1302	    {
1303	      g_cap_err++;
1304	    }
1305	
1306	  ms = mono_ms() - t0;
1307	  if (ms > g_cap_max)
1308	    {
1309	      g_cap_max = ms;
1310	    }
1311	
1312	  if (ms > CAP_SLOW_MS)
1313	    {
1314	      g_cap_slow++;
1315	    }
1316	
1317	  if (f->data != NULL && f->width > 0 && f->height > 0 && f->channels > 0)
1318	    {
1319	      size_t   len  = (size_t)f->width * f->height * f->channels;
1320	      size_t   step = len / 256 + 1;
1321	      uint32_t h    = 2166136261u;
1322	      uint8_t  lo   = 255;
1323	      uint8_t  hi   = 0;
1324	
1325	      for (size_t i = 0; i < len; i += step)
1326	        {
1327	          uint8_t v = f->data[i];
1328	
1329	          h = (h ^ v) * 16777619u;
1330	          if (v < lo)
1331	            {
1332	              lo = v;
1333	            }
1334	
1335	          if (v > hi)
1336	            {
1337	              hi = v;
1338	            }
1339	        }
1340	
1341	      /* sensor noise makes two real frames differ; a black one may not */
1342	
1343	      if (h == last && hi - lo > 16)
1344	        {
1345	          g_cap_same++;
1346	        }
1347	
1348	      last = h;
1349	    }
1350	
1351	  g_cap_n++;
1352	}
