168	+int velapaw_store_put(const char *name, const void *buf, size_t len)
169	+{
170	+  char path[96];
171	+  ssize_t n;
172	+  int fd;
173	+
174	+  if (name == NULL || buf == NULL || !vp_ensure_dir() ||
175	+      vp_path(path, sizeof(path), name) < 0)
176	+    {
177	+      return -1;
178	+    }
179	+
180	+  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
181	+  if (fd < 0)
182	+    {
183	+      return -1;
184	+    }
185	+
186	+  n = write(fd, buf, len);
187	+  if (close(fd) < 0)
188	+    {
189	+      return -1;
190	+    }
191	+
192	+  return n == (ssize_t)len ? 0 : -1;
193	+}
