199	+  int fd;
200	+
201	+  if (name == NULL || buf == NULL || vp_path(path, sizeof(path), name) < 0)
202	+    {
203	+      return -1;
204	+    }
205	+
206	+  fd = open(path, O_RDONLY);
207	+  if (fd < 0)
208	+    {
209	+      return -1;
210	+    }
211	+
212	+  n = read(fd, buf, len);
213	+  close(fd);
214	+  return n < 0 ? -1 : (int)n;
