222	+  if (line == NULL || !vp_ensure_dir())
223	+    {
224	+      return;
225	+    }
226	+
227	+  /* unlink first: whether rename() replaces an existing target is up to
228	+   * the filesystem, and this must not depend on it. */
229	+
230	+  if (stat(VP_HEALTH, &st) == 0 && st.st_size >= VP_HEALTH_MAX)
231	+    {
