282	+/****************************************************************************
283	+ * staying up: console, health log, stall monitor
284	+ *
285	+ * The console is CDC-ACM with a 193-byte TX buffer.  When the host stops
286	+ * reading it -- PuTTY closed, the port lost, the PC asleep -- the buffer fills
287	+ * and the next blocking writer (the agent logs through syslog) waits inside
288	+ * the serial driver holding its TX lock.  Every later console write, on any
289	+ * thread, queues behind that lock.  The O_NONBLOCK set in velapaw_ui_run
290	+ * (which is what keeps a board with no PC at all running) does not help
291	+ * here: the lock is taken before the flag is looked at.  A board left running
292	+ * froze with nothing on screen to say why.  uprintf() asks the driver for the free
293	+ * space first (FIONSPACE takes only a spinlock) and drops the line when the
294	+ * buffer stays full.  It writes the fd directly: stdio's FILE lock is shared
295	+ * by every thread of the task, and a thread stuck in printf holds it.  Prints
296	+ * inside the feeder, TFLM and identity modules are not gated.
297	+ *
298	+ * What has to survive goes to flash instead: health.log in the velapaw data
299	+ * dir gets a line at boot, every 10 minutes and at a stall.
300	+ *
301	+ * The stall monitor resets the board when the UI loop has not come round for
302	+ * STALL_UI_MS (STALL_FEED_MS while the feeder motor turns: a 50 g portion is
303	+ * some 3400 steps), or the inference worker has been inside one request for
304	+ * STALL_INF_MS.  It does no I/O and takes no lock, so what wedged the others
305	+ * cannot wedge it; the note thread writes the STALL line and the monitor
306	+ * waits up to STALL_NOTE_MS for it.  Meals are marked fed before the motor
307	+ * turns (fed_save), so the reset cannot serve one twice.  A CPU stuck with
308	+ * interrupts off is not covered: this build has no hardware watchdog.
309	+ ****************************************************************************/
310	+
311	+#define CON_TRIES       5         /* FIONSPACE polls before a line is dropped */
312	+#define CON_RETRY_MS    10
313	+#define CON_CHUNK       96        /* longer lines go out in pieces */
314	+#define STALL_UI_MS     120000
315	+#define STALL_FEED_MS   600000
316	+#define STALL_INF_MS    60000     /* one embed takes ~1.3 s */
317	+#define STALL_NOTE_MS   3000
318	+#define HEALTH_MS       600000
319	+#define CAP_SLOW_MS     400
320	+
321	+extern void up_systemreset(void);
322	+extern int  esp32s3_reset_reasons(int cpu);    /* returns soc_reset_reason_t */
323	+
324	+static volatile unsigned long g_con_drop;      /* console lines dropped */
325	+static volatile long          g_ui_beat;       /* UI loop: last time round */
326	+static const char *volatile   g_ui_at = "init";/* ...and what it is doing */
327	+static const char             g_at_feed[] = "feed";  /* g_ui_at: motor running */
328	+static volatile uint32_t      g_ui_tab;
329	+static volatile long          g_inf_beat;      /* worker; 0 = never ran */
330	+static volatile unsigned long g_inf_n;         /* embeds finished */
331	+static volatile unsigned long g_rec_hit;       /* Recognize: pet handled */
332	+static volatile unsigned long g_rec_miss;      /* ...gave up, nobody known */
333	+static volatile long          g_cap_max;       /* slowest grab this period */
334	+static volatile unsigned long g_cap_slow;      /* grabs over CAP_SLOW_MS */
335	+static volatile unsigned long g_cap_same;      /* frame equal to the last */
336	+static volatile unsigned long g_cap_err;       /* the HAL said it failed */
337	+static volatile int           g_stall;         /* 1 UI, 2 worker */
338	+static volatile long          g_stall_age;     /* s since its last beat */
339	+static const char *volatile   g_stall_at;
