345	+/* Room for `need` bytes in the console TX buffer, waiting up to CON_TRIES x
346	+ * CON_RETRY_MS for the host to drain it.  1 when the driver cannot tell. */
347	+static int con_ok(int need)
348	+{
349	+#ifdef FIONSPACE
350	+  for (int i = 0; i < CON_TRIES; i++)
351	+    {
352	+      int room;
353	+
354	+      if (ioctl(STDOUT_FILENO, FIONSPACE, (unsigned long)(uintptr_t)&room) < 0
355	+          || room >= need)
356	+        {
357	+          return 1;
358	+        }
359	+
360	+      usleep(CON_RETRY_MS * 1000);
361	+    }
362	+
363	+  return 0;
364	+#else
365	+  (void)need;
366	+  return 1;
367	+#endif
368	+}
