432	+static void *stall_monitor(void *arg)
433	+{
434	+  (void)arg;
435	+  for (;;)
436	+    {
437	+      long now;
438	+      long ui;
439	+      long inf;
440	+      int  kind;
441	+
442	+      sleep(5);
443	+      now  = mono_ms();
444	+      ui   = now - g_ui_beat;
445	+      inf  = g_inf_beat != 0 ? now - g_inf_beat : 0;
446	+      kind = ui > (g_ui_at == g_at_feed ? STALL_FEED_MS : STALL_UI_MS) ? 1 :
447	+             inf > STALL_INF_MS ? 2 : 0;
448	+      if (kind == 0)
449	+        {
450	+          continue;
451	+        }
452	+
453	+      g_stall_age = (kind == 1 ? ui : inf) / 1000;
454	+      g_stall_at  = g_ui_at;
455	+      g_stall     = kind;
456	+      for (int i = 0; i < STALL_NOTE_MS / 100 && !g_stall_noted; i++)
457	+        {
458	+          usleep(100000);
459	+        }
460	+
461	+      up_systemreset();
462	+    }
463	+
464	+  return NULL;
465	+}
