515	+static void stall_start(void)
516	+{
517	+  struct sched_param sp;
518	+  pthread_attr_t attr;
519	+  pthread_t tid;
520	+  int prio = 100;
521	+  int pmax = sched_get_priority_max(SCHED_FIFO);
522	+  int ok = 0;
523	+
524	+  if (sched_getparam(0, &sp) == 0)
525	+    {
526	+      prio = sp.sched_priority;
527	+    }
528	+
529	+  if (pmax > 10 && prio > pmax - 10)
530	+    {
531	+      prio = pmax - 10;
532	+    }
533	+
534	+  pthread_attr_init(&attr);
535	+  pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
536	+
537	+  pthread_attr_setstacksize(&attr, 2048);
538	+  sp.sched_priority = prio + 10;
539	+  pthread_attr_setschedparam(&attr, &sp);
540	+  if (pthread_create(&tid, &attr, stall_monitor, NULL) == 0)
541	+    {
542	+      pthread_detach(tid);
543	+      ok++;
544	+    }
545	+
546	+  pthread_attr_setstacksize(&attr, 6144);
547	+  sp.sched_priority = prio + 5;
548	+  pthread_attr_setschedparam(&attr, &sp);
549	+  if (pthread_create(&tid, &attr, stall_note, NULL) == 0)
550	+    {
551	+      pthread_detach(tid);
552	+      ok++;
553	+    }
554	+
555	+  pthread_attr_destroy(&attr);
556	+  uprintf("velapaw: stall monitor %s\n", ok == 2 ? "armed" : "NOT started");
