682	+/* Mean brightness of a 4x4 grid, from every 4th pixel each way (~1000
683	+ * reads): cheap enough for each preview frame.  -1 if there is no picture. */
684	+static int scene_sig(const struct velapaw_frame *f, uint8_t sig[16])
685	+{
686	+  int cw;
687	+  int chh;
688	+
689	+  if (f == NULL || f->data == NULL || f->channels < 1 ||
690	+      f->width < 16 || f->height < 16)
691	+    {
692	+      return -1;
693	+    }
694	+
695	+  cw  = f->width / 4;
696	+  chh = f->height / 4;
697	+  for (int cy = 0; cy < 4; cy++)
698	+    {
699	+      for (int cx = 0; cx < 4; cx++)
700	+        {
701	+          uint32_t sum = 0;
702	+          uint32_t cnt = 0;
703	+
704	+          for (int y = cy * chh; y < (cy + 1) * chh; y += 4)
705	+            {
706	+              const uint8_t *row = f->data +
707	+                                   (size_t)y * f->width * f->channels;
708	+
709	+              for (int x = cx * cw; x < (cx + 1) * cw; x += 4)
710	+                {
711	+                  const uint8_t *px = row + (size_t)x * f->channels;
712	+
713	+                  sum += f->channels >= 3 ?
714	+                         (77u * px[0] + 150u * px[1] + 29u * px[2]) >> 8 :
715	+                         px[0];
716	+                  cnt++;
717	+                }
718	+            }
719	+
720	+          sig[cy * 4 + cx] = (uint8_t)(cnt != 0 ? sum / cnt : 0);
721	+        }
722	+    }
723	+
724	+  return 0;
725	+}
