727	+/* Something moved: SIG_MIN_CELLS cells changed beyond the shift of the whole
728	+ * picture, or the whole picture shifted a lot.  Sensor noise and exposure
729	+ * drift stay under both. */
730	+static int scene_moved(const uint8_t ref[16], const uint8_t sig[16])
731	+{
732	+  int shift = 0;
733	+  int cells = 0;
734	+
735	+  for (int i = 0; i < 16; i++)
736	+    {
737	+      shift += sig[i] - ref[i];
738	+    }
739	+
740	+  shift /= 16;
741	+  if (shift > SIG_SHIFT_MAX || shift < -SIG_SHIFT_MAX)
742	+    {
743	+      return 1;
744	+    }
745	+
746	+  for (int i = 0; i < 16; i++)
747	+    {
748	+      int dv = sig[i] - ref[i] - shift;
749	+
750	+      if (dv > SIG_CELL_DIFF || dv < -SIG_CELL_DIFF)
751	+        {
752	+          cells++;
753	+        }
754	+    }
755	+
756	+  return cells >= SIG_MIN_CELLS;
757	+}
