266	static void wall_set_min(int minofday)   /* set clock to today at HH:MM */
267	{
268	  struct timespec ts;
269	  clock_gettime(CLOCK_REALTIME, &ts);
270	  if (minofday < 0) minofday += 1440;
271	  minofday %= 1440;
272	  ts.tv_sec  = (ts.tv_sec / 86400) * 86400 + (long)minofday * 60;
273	  ts.tv_nsec = 0;
274	  clock_settime(CLOCK_REALTIME, &ts);
275	  board_rtc_settime(ts.tv_sec);   /* survive reset / power-off */
276	}
