766	/* Minutes until this pet may eat again, 0 = now.  Two meals can be due at
767	 * once (one was missed, or after a reset), and now that recognition wakes by
768	 * itself the second followed the first within seconds.  g_last_fed was meant
769	 * to space them, but nothing ever read it. */
770	static int feed_wait_min(int id, long today, int nowm)
771	{
772	  int wait_min = 0;
773	
774	  for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
775	    {
776	      int ago = nowm - g_meal_fed_min[id][k];
777	
778	      if (g_meal_fed_day[id][k] == today && g_meal_fed_g[id][k] > 0 &&
779	          ago >= 0 && ago < FEED_GAP_MIN && FEED_GAP_MIN - ago > wait_min)
780	        {
781	          wait_min = FEED_GAP_MIN - ago;
782	        }
783	    }
784	
785	  return wait_min;
786	}
