788	/* A meal reached its time in the last MEAL_POLL_WIN_MIN minutes and is
789	 * neither eaten nor skipped: worth a look at the bowl even when the picture
790	 * has not changed.  Not all day -- a pet that never came must not keep the
791	 * camera and the model busy until midnight.  UI thread only. */
792	static int meal_window_open(void)
793	{
794	  long today = wall_day();
795	  int  nowm  = wall_min();
796	  int  n     = velapaw_identity_count();
797	
798	  for (int i = 0; i < n && i < VELAPAW_MAX_PETS; i++)
799	    {
800	      const struct velapaw_pet *p = velapaw_identity_get(i);
801	
802	      for (int k = 0; p != NULL && k < VELAPAW_MAX_MEALS; k++)
803	        {
804	          int since = nowm - p->meal_min[k];
805	
806	          if (p->meal_min[k] >= 0 && since >= 0 &&
807	              since < MEAL_POLL_WIN_MIN &&
808	              g_meal_fed_day[i][k] != today && !g_meal_skipped[i][k])
809	            {
810	              return 1;
811	            }
812	        }
813	    }
