"""Dump the geometry, text styles and media of a .pptx (read-only on the source).

usage: python -I inspect_pptx.py <template.pptx> <extract-dir> <report.txt>
Extracts ppt/media/* into <extract-dir>/media and writes a text report.
"""
import os, re, sys, zipfile
import xml.etree.ElementTree as ET

src, xdir, rep = sys.argv[1], sys.argv[2], sys.argv[3]
NS = {
    "a": "http://schemas.openxmlformats.org/drawingml/2006/main",
    "p": "http://schemas.openxmlformats.org/presentationml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}
RID = "{%s}id" % NS["r"]
EMBED = "{%s}embed" % NS["r"]
out = []
w = out.append

z = zipfile.ZipFile(src)
names = z.namelist()

# media out, flat, safe names only
mdir = os.path.join(xdir, "media")
os.makedirs(mdir, exist_ok=True)
for n in names:
    if n.startswith("ppt/media/"):
        base = n.rsplit("/", 1)[1]
        if not re.fullmatch(r"[A-Za-z0-9_.-]{1,80}", base):
            w("SKIP odd media name %r" % n)
            continue
        with open(os.path.join(mdir, base), "wb") as f:
            f.write(z.read(n))

pres = ET.fromstring(z.read("ppt/presentation.xml"))
sz = pres.find("p:sldSz", NS)
cx, cy = int(sz.get("cx")), int(sz.get("cy"))
S = 1920.0 / cx          # EMU -> px on a 1920-wide canvas
w("slide size EMU %d x %d  -> 1 px = %.1f EMU; 1pt font = %.3f px" % (cx, cy, 1 / S, 12700 * S))
w("")
w("== media")
try:
    from PIL import Image
except Exception:
    Image = None
for n in sorted(x for x in names if x.startswith("ppt/media/")):
    info = z.getinfo(n)
    dims = ""
    if Image and re.search(r"\.(png|jpe?g|gif|bmp|webp)$", n, re.I):
        try:
            im = Image.open(os.path.join(mdir, n.rsplit("/", 1)[1]))
            dims = "%dx%d %s" % (im.size[0], im.size[1], im.mode)
        except Exception as e:
            dims = "?" + type(e).__name__
    w("  %-40s %9d  %s" % (n, info.file_size, dims))
w("")


def rels(path):
    d, b = path.rsplit("/", 1)
    rp = d + "/_rels/" + b + ".rels"
    m = {}
    if rp in names:
        for r in ET.fromstring(z.read(rp)):
            m[r.get("Id")] = (r.get("Target"), r.get("Type").rsplit("/", 1)[1])
    return m


def px(v):
    return int(round(int(v) * S))


def color_of(el):
    if el is None:
        return ""
    s = el.find(".//a:srgbClr", NS)
    if s is not None:
        alpha = s.find("a:alpha", NS)
        return "#" + s.get("val") + ("@%d%%" % (int(alpha.get("val")) // 1000) if alpha is not None else "")
    s = el.find(".//a:schemeClr", NS)
    if s is not None:
        return "scheme:" + s.get("val")
    return ""


def fill_of(sppr):
    if sppr is None:
        return ""
    out = []
    sf = sppr.find("a:solidFill", NS)
    if sf is not None:
        out.append("fill " + color_of(sf))
    gf = sppr.find("a:gradFill", NS)
    if gf is not None:
        stops = ["%s@%d" % (color_of(gs), int(gs.get("pos")) // 1000) for gs in gf.findall(".//a:gs", NS)]
        lin = gf.find("a:lin", NS)
        ang = (int(lin.get("ang")) / 60000.0) if lin is not None and lin.get("ang") else None
        out.append("grad[%s]%s" % (" ".join(stops), (" ang%.0f" % ang) if ang is not None else ""))
    ln = sppr.find("a:ln", NS)
    if ln is not None and ln.find("a:noFill", NS) is None:
        lw = ln.get("w")
        out.append("line %s %s" % (("%.1fpx" % (int(lw) * S)) if lw else "", color_of(ln)))
    geom = sppr.find("a:prstGeom", NS)
    if geom is not None:
        out.append("geom " + geom.get("prst"))
        av = geom.find("a:avLst", NS)
        if av is not None:
            for g in av:
                out.append("%s=%s" % (g.get("name"), g.get("fmla")))
    return " ".join(out)


def xfrm_of(el):
    x = el.find(".//a:xfrm", NS)
    if x is None:
        return ""
    o, e = x.find("a:off", NS), x.find("a:ext", NS)
    if o is None or e is None:
        return ""
    rot = x.get("rot")
    return "x%d y%d w%d h%d%s" % (px(o.get("x")), px(o.get("y")), px(e.get("cx")), px(e.get("cy")),
                                 (" rot%.0f" % (int(rot) / 60000.0)) if rot else "")


def runs_of(el):
    res = []
    for para in el.findall(".//a:p", NS):
        algn = para.find("a:pPr", NS)
        al = algn.get("algn") if algn is not None and algn.get("algn") else ""
        lns = para.find("a:pPr/a:lnSpc/a:spcPct", NS)
        lsp = (" ls%.2f" % (int(lns.get("val")) / 100000.0)) if lns is not None else ""
        parts = []
        for r in para.findall("a:r", NS):
            t = r.find("a:t", NS)
            rp = r.find("a:rPr", NS)
            txt = t.text if t is not None and t.text else ""
            st = []
            if rp is not None:
                if rp.get("sz"):
                    st.append("%.1fpt=%.1fpx" % (int(rp.get("sz")) / 100.0, int(rp.get("sz")) / 100.0 * 12700 * S))
                if rp.get("b") == "1":
                    st.append("B")
                c = color_of(rp.find("a:solidFill", NS))
                if c:
                    st.append(c)
                g = rp.find("a:gradFill", NS)
                if g is not None:
                    st.append("grad[%s]" % " ".join(color_of(gs) for gs in g.findall(".//a:gs", NS)))
                for tag in ("a:latin", "a:ea"):
                    f = rp.find(tag, NS)
                    if f is not None and f.get("typeface"):
                        st.append(tag[2:] + "=" + f.get("typeface"))
                if rp.get("spc"):
                    st.append("spc%s" % rp.get("spc"))
            if txt.strip():
                parts.append("%r{%s}" % (txt, ",".join(st)))
        if parts:
            res.append("      para%s%s: %s" % ((" " + al) if al else "", lsp, " ".join(parts)))
    return res


def walk(tree, rel, depth=0):
    ind = "  " * depth
    for ch in tree:
        tag = ch.tag.rsplit("}", 1)[1]
        if tag in ("nvGrpSpPr", "grpSpPr"):
            continue
        name = ""
        cnv = ch.find(".//p:cNvPr", NS)
        if cnv is not None:
            name = cnv.get("name") or ""
        if tag == "grpSp":
            w("%s  GROUP %r %s" % (ind, name, xfrm_of(ch.find("p:grpSpPr", NS)) if ch.find("p:grpSpPr", NS) is not None else ""))
            walk(ch, rel, depth + 1)
        elif tag == "sp":
            sppr = ch.find("p:spPr", NS)
            ph = ch.find(".//p:nvPr/p:ph", NS)
            phs = (" ph=%s/%s" % (ph.get("type"), ph.get("idx"))) if ph is not None else ""
            w("%s  SP %r %s %s%s" % (ind, name, xfrm_of(sppr) if sppr is not None else "", fill_of(sppr), phs))
            for line in runs_of(ch):
                w(ind + line)
        elif tag == "pic":
            bl = ch.find(".//a:blip", NS)
            tgt = rel.get(bl.get(EMBED), ("?", ""))[0] if bl is not None else "?"
            w("%s  PIC %r %s -> %s" % (ind, name, xfrm_of(ch.find("p:spPr", NS)), tgt))
        elif tag == "cxnSp":
            w("%s  LINE %r %s %s" % (ind, name, xfrm_of(ch.find("p:spPr", NS)), fill_of(ch.find("p:spPr", NS))))
        elif tag == "graphicFrame":
            w("%s  FRAME %r %s" % (ind, name, xfrm_of(ch)))
            tbl = ch.find(".//a:tbl", NS)
            if tbl is not None:
                cols = [px(gc.get("w")) for gc in tbl.findall("a:tblGrid/a:gridCol", NS)]
                w("%s    table cols %s" % (ind, cols))
                for i, tr in enumerate(tbl.findall("a:tr", NS)):
                    cells = []
                    for tc in tr.findall("a:tc", NS):
                        tcpr = tc.find("a:tcPr", NS)
                        f = color_of(tcpr.find("a:solidFill", NS)) if tcpr is not None and tcpr.find("a:solidFill", NS) is not None else ""
                        rr = runs_of(tc)
                        cells.append("%s %s" % (f, (rr[0].strip() if rr else "")[:90]))
                    w("%s    row%d h%d: %s" % (ind, i, px(tr.get("h")), " | ".join(cells)))
        else:
            w("%s  %s %r" % (ind, tag.upper(), name))


def dump(path, title):
    root = ET.fromstring(z.read(path))
    rel = rels(path)
    w("== %s  (%s)" % (title, path))
    bg = root.find(".//p:bg", NS)
    if bg is not None:
        bp = bg.find("p:bgPr", NS)
        if bp is not None:
            bl = bp.find(".//a:blip", NS)
            if bl is not None:
                w("  BG image -> %s" % rel.get(bl.get(EMBED), ("?",))[0])
            w("  BG %s" % fill_of(bp))
        else:
            w("  BG ref %s" % color_of(bg))
    for k, (t, ty) in sorted(rel.items()):
        if ty in ("slideLayout", "slideMaster", "video", "media", "image", "audio"):
            w("  rel %s %s -> %s" % (k, ty, t))
    tree = root.find(".//p:spTree", NS)
    walk(tree, rel)
    w("")


for n in sorted(x for x in names if re.fullmatch(r"ppt/slideMasters/slideMaster\d+\.xml", x)):
    dump(n, "MASTER")
used_layouts = set()
slides = sorted((x for x in names if re.fullmatch(r"ppt/slides/slide\d+\.xml", x)),
                key=lambda s: int(re.search(r"(\d+)", s.rsplit("/", 1)[1]).group(1)))
for s in slides:
    for k, (t, ty) in rels(s).items():
        if ty == "slideLayout":
            used_layouts.add("ppt/slideLayouts/" + t.rsplit("/", 1)[1])
for n in sorted(used_layouts):
    dump(n, "LAYOUT")
for i, s in enumerate(slides, 1):
    dump(s, "SLIDE %d" % i)

# theme fonts and colours
for n in sorted(x for x in names if re.fullmatch(r"ppt/theme/theme\d+\.xml", x)):
    t = ET.fromstring(z.read(n))
    cs = t.find(".//a:clrScheme", NS)
    if cs is not None:
        w("== %s colours: %s" % (n, " ".join("%s=%s" % (c.tag.rsplit('}', 1)[1], color_of(c)) for c in cs)))
    fs = t.find(".//a:fontScheme", NS)
    if fs is not None:
        for kind in ("majorFont", "minorFont"):
            k = fs.find("a:" + kind, NS)
            if k is not None:
                w("   %s latin=%s ea=%s" % (kind, k.find("a:latin", NS).get("typeface"),
                                          (k.find("a:ea", NS).get("typeface") if k.find("a:ea", NS) is not None else "")))
w("== embedded fonts: %s" % [x for x in names if x.startswith("ppt/fonts/")])

with open(rep, "w", encoding="utf-8") as f:
    f.write("\n".join(out) + "\n")
print("report lines", len(out))

