700	 * meal state that survives a reset, and when to look again
701	 *
702	 * Which meals were eaten today, when and how much, and which the owner
703	 * skipped, lived only in RAM: every reset -- now including the stall
704	 * monitor's -- served the day's meals again.  fed.bin keeps them.  A skip
705	 * counts only for the day it was set.
706	 ****************************************************************************/
707	
708	#define FEED_GAP_MIN       20     /* minutes between two meals of one pet */
709	#define REARM_HIT_MS       30000  /* after a pet was handled */
710	#define REARM_MISS_MS      3000   /* after nobody known: doubles... */
711	#define REARM_MISS_MAX_MS  20000  /* ...up to this */
712	#define MEAL_POLL_MS       60000  /* one look a minute while a meal is due */
713	#define MEAL_POLL_WIN_MIN  30     /* ...for its first 30 minutes */
714	#define SIG_CELL_DIFF      20     /* scene_moved(): a cell changed */
715	#define SIG_MIN_CELLS      2      /* ...this many of the 16 */
716	#define SIG_SHIFT_MAX      48     /* ...or the whole picture (a light) */
717	#define FED_MAGIC          0x56504631u   /* "VPF1" */
718	
719	struct fed_state
720	{
721	  uint32_t magic;
722	  uint32_t size;                  /* a geometry change voids the file */
723	  long     day;                   /* wall_day() at save */
724	  long     fed_day[VELAPAW_MAX_PETS][VELAPAW_MAX_MEALS];
725	  int      fed_min[VELAPAW_MAX_PETS][VELAPAW_MAX_MEALS];
726	  int      fed_g[VELAPAW_MAX_PETS][VELAPAW_MAX_MEALS];
727	  uint8_t  skipped[VELAPAW_MAX_PETS][VELAPAW_MAX_MEALS];
728	};
729	
730	/* After every change to the four arrays.  UI thread only. */
731	static void fed_save(void)
732	{
733	  struct fed_state s;
734	
735	  memset(&s, 0, sizeof(s));
736	  s.magic = FED_MAGIC;
737	  s.size  = sizeof(s);
738	  s.day   = wall_day();
739	  memcpy(s.fed_day, g_meal_fed_day, sizeof(s.fed_day));
740	  memcpy(s.fed_min, g_meal_fed_min, sizeof(s.fed_min));
741	  memcpy(s.fed_g,   g_meal_fed_g,   sizeof(s.fed_g));
742	  memcpy(s.skipped, g_meal_skipped, sizeof(s.skipped));
743	  if (velapaw_store_put("fed.bin", &s, sizeof(s)) < 0)
744	    {
745	      uprintf("velapaw: fed.bin save failed\n");
746	    }
747	}
748	
749	static void fed_load(void)
750	{
751	  struct fed_state s;
752	
753	  if (velapaw_store_get("fed.bin", &s, sizeof(s)) != (int)sizeof(s) ||
754	      s.magic != FED_MAGIC || s.size != sizeof(s))
755	    {
756	      return;
757	    }
758	
759	  memcpy(g_meal_fed_day, s.fed_day, sizeof(g_meal_fed_day));
760	  memcpy(g_meal_fed_min, s.fed_min, sizeof(g_meal_fed_min));
761	  memcpy(g_meal_fed_g,   s.fed_g,   sizeof(g_meal_fed_g));
762	  if (s.day == wall_day())
763	    {
764	      memcpy(g_meal_skipped, s.skipped, sizeof(g_meal_skipped));
765	    }
766	
767	  uprintf("velapaw: meal state restored from fed.bin\n");
