822	/* Mean brightness of a 4x4 grid, from every 4th pixel each way (~1000
823	 * reads): cheap enough for each preview frame.  -1 if there is no picture. */
824	static int scene_sig(const struct velapaw_frame *f, uint8_t sig[16])
825	{
826	  int cw;
827	  int chh;
828	
829	  if (f == NULL || f->data == NULL || f->channels < 1 ||
830	      f->width < 16 || f->height < 16)
831	    {
832	      return -1;
833	    }
834	
835	  cw  = f->width / 4;
836	  chh = f->height / 4;
837	  for (int cy = 0; cy < 4; cy++)
838	    {
839	      for (int cx = 0; cx < 4; cx++)
840	        {
841	          uint32_t sum = 0;
842	          uint32_t cnt = 0;
843	
844	          for (int y = cy * chh; y < (cy + 1) * chh; y += 4)
845	            {
846	              const uint8_t *row = f->data +
847	                                   (size_t)y * f->width * f->channels;
848	
849	              for (int x = cx * cw; x < (cx + 1) * cw; x += 4)
850	                {
851	                  const uint8_t *px = row + (size_t)x * f->channels;
852	
853	                  sum += f->channels >= 3 ?
854	                         (77u * px[0] + 150u * px[1] + 29u * px[2]) >> 8 :
855	                         px[0];
856	                  cnt++;
857	                }
858	            }
859	
860	          sig[cy * 4 + cx] = (uint8_t)(cnt != 0 ? sum / cnt : 0);
861	        }
862	    }
863	
864	  return 0;
865	}
