735	/****************************************************************************
736	 * Small state files and the health log
737	 *
738	 * Raw open/write/close: no stdio buffer to allocate and nothing left to
739	 * flush, which matters for the health log -- the stall-note thread writes it
740	 * seconds before the board is reset.  littlefs commits a file at close, so a
741	 * reset part-way through a put leaves the previous copy, not a torn one.
742	 ****************************************************************************/
743	
744	#define VP_HEALTH     VP_DIR "/health.log"
745	#define VP_HEALTH_OLD VP_DIR "/health.old"
746	#define VP_HEALTH_MAX 4096     /* then rotate: the pair keeps ~8 KB, ~8 h */
747	
748	static int vp_path(char *path, size_t size, const char *name)
749	{
750	  int n = snprintf(path, size, VP_DIR "/%s", name);
751	
752	  return (n > 0 && (size_t)n < size) ? 0 : -1;
753	}
754	
755	int velapaw_store_put(const char *name, const void *buf, size_t len)
756	{
757	  char path[96];
758	  ssize_t n;
759	  int fd;
760	
761	  if (name == NULL || buf == NULL || !vp_ensure_dir() ||
762	      vp_path(path, sizeof(path), name) < 0)
763	    {
764	      return -1;
765	    }
766	
767	  fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
768	  if (fd < 0)
769	    {
770	      return -1;
771	    }
772	
773	  n = write(fd, buf, len);
774	  if (close(fd) < 0)
775	    {
776	      return -1;
777	    }
778	
779	  return n == (ssize_t)len ? 0 : -1;
780	}
781	
782	int velapaw_store_get(const char *name, void *buf, size_t len)
783	{
784	  char path[96];
785	  ssize_t n;
786	  int fd;
787	
788	  if (name == NULL || buf == NULL || vp_path(path, sizeof(path), name) < 0)
789	    {
790	      return -1;
791	    }
792	
793	  fd = open(path, O_RDONLY);
794	  if (fd < 0)
795	    {
796	      return -1;
797	    }
798	
799	  n = read(fd, buf, len);
800	  close(fd);
801	  return n < 0 ? -1 : (int)n;
802	}
803	
804	void velapaw_store_log_health(const char *line)
805	{
806	  struct stat st;
807	  int fd;
808	
809	  if (line == NULL || !vp_ensure_dir())
810	    {
811	      return;
812	    }
813	
814	  /* unlink first: whether rename() replaces an existing target is up to
815	   * the filesystem, and this must not depend on it. */
816	
817	  if (stat(VP_HEALTH, &st) == 0 && st.st_size >= VP_HEALTH_MAX)
818	    {
819	      unlink(VP_HEALTH_OLD);
820	      rename(VP_HEALTH, VP_HEALTH_OLD);
821	    }
822	
823	  fd = open(VP_HEALTH, O_WRONLY | O_CREAT | O_APPEND, 0644);
824	  if (fd < 0)
825	    {
826	      return;
827	    }
828	
829	  write(fd, line, strlen(line));
830	  write(fd, "\n", 1);
831	  close(fd);
832	}
