2595	static void refresh_trends(void)
2596	{
2597	  if (g_trend_chart == NULL)
2598	    {
2599	      return;
2600	    }
2601	  int cnt = velapaw_identity_count();
2602	  if (cnt == 0)
2603	    {
2604	      lv_label_set_text(g_trend_title, T(S_TRENDS_ENROLL_FIRST));
2605	      lv_label_set_text(g_trend_stats, "");
2606	      lv_label_set_text(g_trend_val, "");
2607	      return;
2608	    }
2609	  if (g_trend_pet >= cnt)
2610	    {
2611	      g_trend_pet = 0;
2612	    }
2613	  const struct velapaw_pet *pet = velapaw_identity_get(g_trend_pet);
2614	  int n = g_trend_month ? VELAPAW_HIST_DAYS : VELAPAW_WEEK_DAYS;
2615	  lv_chart_set_point_count(g_trend_chart, n);
2616	  int maxg = 1;
2617	  long sum = 0;
2618	  for (int i = 0; i < n; i++)
2619	    {
2620	      int db = (n - 1) - i;              /* i=0 oldest ... i=n-1 today */
2621	      int v = velapaw_store_day_total(g_trend_pet, db);
2622	      g_trend_vals[i] = v;
2623	      sum += v;
2624	      if (v > maxg)
2625	        {
2626	          maxg = v;
2627	        }
2628	    }
2629	  /* Average over COMPLETED days only -- exclude today (the last index), which is
2630	   * still filling (often 0 g so far) and would drag the mean below every past
2631	   * day, making them all read above-average (all green). */
2632	  { long csum = sum - g_trend_vals[n - 1];
2633	    g_trend_avg = (n > 1) ? (int32_t)(csum / (n - 1)) : g_trend_vals[0]; }
2634	  lv_chart_set_range(g_trend_chart, LV_CHART_AXIS_PRIMARY_Y, 0, maxg);
2635	  for (int i = 0; i < n; i++)
2636	    {
2637	      lv_chart_set_value_by_id(g_trend_chart, g_trend_ser, i, g_trend_vals[i]);
2638	    }
2639	  lv_chart_refresh(g_trend_chart);
2640	
2641	  /* appetite line: each day's intake as a % of the pet's daily allowance */
2642	  if (g_appet_chart)
2643	    {
2644	      lv_chart_set_point_count(g_appet_chart, n);
2645	      for (int i = 0; i < n; i++)
2646	        {
2647	          int pct = (pet->daily_limit_g > 0)
2648	                    ? (int)(g_trend_vals[i] * 100 / pet->daily_limit_g) : 0;
2649	          lv_chart_set_value_by_id(g_appet_chart, g_appet_ser, i,
2650	                                   pct > 100 ? 100 : pct);
2651	        }
2652	      lv_chart_refresh(g_appet_chart);
2653	    }
2654	
2655	  lv_label_set_text_fmt(g_trend_title, T(S_TREND_TITLE_FMT), pet->name,
2656	                        g_trend_month ? T(S_WIN_30D) : T(S_WIN_7D));
2657	  lv_label_set_text_fmt(g_trend_stats, T(S_TREND_STATS_FMT),
2658	      velapaw_store_today_total(g_trend_pet), pet->daily_limit_g,
2659	      velapaw_store_baseline_g(g_trend_pet),
2660	      velapaw_store_week_total(g_trend_pet),
2661	      velapaw_store_month_total(g_trend_pet),
2662	      pet_appetite_pct(g_trend_pet, pet));
2663	  lv_label_set_text(g_trend_val, T(S_TAP_BAR));
2664	
2665	  /* highlight the active window toggle */
2666	  if (g_btn_week && g_btn_month)
2667	    {
2668	      lv_obj_set_style_bg_color(g_btn_week,
2669	          lv_color_hex(g_trend_month ? COL_BTN : COL_ACCENT), 0);
2670	      lv_obj_set_style_bg_color(g_btn_month,
2671	          lv_color_hex(g_trend_month ? COL_ACCENT : COL_BTN), 0);
2672	    }
2673	
2674	  refresh_bcs_gauge();      /* update the dial for the current pet */
2675	}
