2677	/* Recolour each intake bar by whether that day was at/above the window average:
2678	 * green = a good (>=avg) day, blue = below-average. The colour split IS the
2679	 * baseline, so no separate average line is needed. LVGL 9 draw-task hook. */
2680	static void trend_bar_color_cb(lv_event_t *e)
2681	{
2682	  lv_draw_task_t *task = lv_event_get_draw_task(e);
2683	  /* LVGL 9.1 has no lv_draw_task_get_draw_dsc() (that's 9.2) -- read the base
2684	   * descriptor from the task field, as LVGL 9.1's own chart example does. */
2685	  lv_draw_dsc_base_t *base = task->draw_dsc;
2686	  if (base == NULL || base->part != LV_PART_ITEMS)
2687	    {
2688	      return;                            /* not one of the bars */
2689	    }
2690	  lv_draw_fill_dsc_t *fill = lv_draw_task_get_fill_dsc(task);
2691	  if (fill == NULL)
2692	    {
2693	      return;                            /* not a fill (rectangle) task */
2694	    }
2695	  int n = g_trend_month ? VELAPAW_HIST_DAYS : VELAPAW_WEEK_DAYS;
2696	  uint32_t idx = base->id1;              /* point index (id2 is the series index) */
2697	  if ((int)idx < n)
2698	    {
2699	      fill->color = lv_color_hex(g_trend_vals[idx] >= g_trend_avg
2700	                                 ? COL_FED : COL_ACCENT);
2701	    }
2702	}
