2756	static void refresh_bcs_gauge(void)
2757	{
2758	  if (g_bcs_needle == NULL)
2759	    {
2760	      return;
2761	    }
2762	  int bcs = velapaw_store_get_bcs(g_trend_pet);
2763	  int dx, dy; const char *nm; uint32_t lblcol; uint32_t ndlcol = 0xFFFFFF; /* white */
2764	  switch (bcs)
2765	    {
2766	      case 0:  dx = -54; dy = -31;   nm = T(S_BCS_UNDER); lblcol = COL_COOL; break; /* 210 deg */
2767	      case 1:  dx =   0; dy = -GA_L; nm = T(S_BCS_IDEAL); lblcol = COL_FED;  break; /* 270, up */
2768	      case 2:  dx =  54; dy = -31;   nm = T(S_BCS_OVER);  lblcol = COL_UNK;  break; /* 330 deg */
2769	      default: dx =   0; dy = -36;   nm = T(S_BCS_NA);    lblcol = COL_DIM;
2770	               ndlcol = COL_DIM; break;                                 /* no reading: grey */
2771	    }
2772	  g_bcs_pts[0].x = GA_C;      g_bcs_pts[0].y = GA_C;
2773	  g_bcs_pts[1].x = GA_C + dx; g_bcs_pts[1].y = GA_C + dy;
2774	  lv_line_set_points(g_bcs_needle, g_bcs_pts, 2);
2775	  lv_obj_set_style_line_color(g_bcs_needle, lv_color_hex(ndlcol), 0);
2776	  lv_label_set_text(g_bcs_lbl, nm);
2777	  lv_obj_set_style_text_color(g_bcs_lbl, lv_color_hex(lblcol), 0);
2778	}
