2729	/* ---- BCS gauge: a 3-zone semicircular dial (Trends tab) --------------------
2730	 * BCS is a 3-class score (0 under / 1 ideal / 2 over / -1 none). Three coloured
2731	 * lv_arc bands over the top semicircle (amber | green | amber-red) with an
2732	 * lv_line needle pointing at the current class. Uses only confirmed LVGL 9.1
2733	 * widgets (arc + line) -- no lv_scale sections (their setter API isn't in 9.1).
2734	 * Angles: LVGL arc 0 deg = 3 o'clock, clockwise, so 180->360 is the top half. */
2735	#define GA_D    150                     /* gauge diameter (square) */
2736	#define GA_C    (GA_D / 2)              /* pivot / centre (local)  */
2737	#define GA_L    62                      /* needle length           */
2738	
2739	static lv_obj_t *bcs_zone_arc(lv_obj_t *p, int a0, int a1, uint32_t col)
2740	{
2741	  lv_obj_t *a = lv_arc_create(p);
2742	  lv_obj_set_size(a, GA_D, GA_D);
2743	  lv_obj_center(a);
2744	  lv_obj_remove_flag(a, LV_OBJ_FLAG_CLICKABLE);
2745	  lv_arc_set_bg_angles(a, a0, a1);
2746	  lv_arc_set_angles(a, a0, a0);                       /* no indicator fill */
2747	  lv_obj_set_style_bg_opa(a, LV_OPA_TRANSP, 0);       /* no widget rectangle */
2748	  lv_obj_set_style_arc_color(a, lv_color_hex(col), LV_PART_MAIN);
2749	  lv_obj_set_style_arc_width(a, 18, LV_PART_MAIN);
2750	  lv_obj_set_style_arc_rounded(a, false, LV_PART_MAIN);
2751	  lv_obj_set_style_arc_opa(a, LV_OPA_TRANSP, LV_PART_INDICATOR);
2752	  lv_obj_set_style_bg_opa(a, LV_OPA_TRANSP, LV_PART_KNOB);
2753	  return a;
2754	}
