792	/* A meal reached its time in the last MEAL_POLL_WIN_MIN minutes and is
793	 * neither eaten nor skipped: worth a look at the bowl even when the picture
794	 * has not changed.  Not all day -- a pet that never came must not keep the
795	 * camera and the model busy until midnight.  UI thread only. */
796	static int meal_window_open(void)
797	{
798	  long today = wall_day();
799	  int  nowm  = wall_min();
800	  int  n     = velapaw_identity_count();
801	
802	  for (int i = 0; i < n && i < VELAPAW_MAX_PETS; i++)
803	    {
804	      const struct velapaw_pet *p = velapaw_identity_get(i);
805	
806	      for (int k = 0; p != NULL && k < VELAPAW_MAX_MEALS; k++)
807	        {
808	          int since = nowm - p->meal_min[k];
809	
810	          if (p->meal_min[k] >= 0 && since >= 0 &&
811	              since < MEAL_POLL_WIN_MIN &&
812	              g_meal_fed_day[i][k] != today && !g_meal_skipped[i][k])
813	            {
814	              return 1;
815	            }
816	        }
817	    }
818	
819	  return 0;
820	}
