42	/* A console line that is dropped, not waited for, when the host has stopped
43	 * reading.  Same rule as con_ok() in ui/ui_lvgl.c, which explains why a
44	 * plain printf can block the UI thread for good.
45	 */
46	static void vp_say(const char *fmt, ...) __attribute__((format(printf, 1, 2)));
47	static void vp_say(const char *fmt, ...)
48	{
49	  char line[128];
50	  va_list ap;
51	  int n;
52	
53	  va_start(ap, fmt);
54	  n = vsnprintf(line, sizeof(line), fmt, ap);
55	  va_end(ap);
56	  if (n <= 0)
57	    {
58	      return;
59	    }
60	
61	  if (n > (int)sizeof(line) - 1)
62	    {
63	      n = sizeof(line) - 1;
64	    }
65	
66	#ifdef FIONSPACE
67	  for (int i = 0; i < 5; i++)
68	    {
69	      int room;
70	
71	      if (ioctl(STDOUT_FILENO, FIONSPACE, (unsigned long)(uintptr_t)&room) < 0
72	          || room >= n)
73	        {
74	          write(STDOUT_FILENO, line, n);
75	          return;
76	        }
77	
78	      usleep(10000);
79	    }
80	#else
81	  write(STDOUT_FILENO, line, n);
82	#endif
83	}
