324	static void vp_feedlog_append(const struct velapaw_feed_event *ev)
325	{
326	  struct stat st;
327	  bool fresh;
328	  char when[40];
329	
330	  if (!vp_ensure_dir())
331	    {
332	      return;
333	    }
334	
335	  /* Restart rather than grow without bound. */
336	  fresh = (stat(VP_FEEDLOG, &st) != 0) || (st.st_size > VP_LOG_MAX);
337	
338	  FILE *f = fopen(VP_FEEDLOG, fresh ? "w" : "a");
339	  if (f == NULL)
340	    {
341	      return;
342	    }
343	
344	  if (fresh)
345	    {
346	      fputs("# VelaPaw Feed Log\n\n"
347	            "Most recent feeding events, newest last.\n\n", f);
348	    }
349	
350	  if (ev->ts > VP_TS_SANE)
351	    {
352	      struct tm tmv;
353	      localtime_r(&ev->ts, &tmv);
354	      strftime(when, sizeof(when), "%Y-%m-%d %H:%M", &tmv);
355	    }
356	  else
357	    {
358	      snprintf(when, sizeof(when), "epoch %ld (clock unset)", (long)ev->ts);
359	    }
360	
361	  const struct velapaw_pet *p = velapaw_identity_get(ev->pet_id);
362	
363	  fprintf(f, "- [%s] %s fed %d g (match %.2f, model %s)\n",
364	          when,
365	          (p != NULL && p->name[0]) ? p->name : "(unnamed)",
366	          ev->grams, ev->score, ev->model ? ev->model : "?");
367	
368	  fclose(f);
369	}
