712	/* today_total() does not reconcile, so a day that ended at the daily cap made
713	 * the feeder refuse every meal of the next one: the first meal saw
714	 * yesterday's grams, was marked "limit hit" and nothing was fed -- and with
715	 * no feed, nothing ever rolled the window.  Only a feed or a reboot did.
716	 * Called by the UI when the day number changes.  UI thread only --
717	 * vp_sync_day() is not safe against a second caller.
718	 */
719	void velapaw_store_sync_day(void)
720	{
721	  long before = g_hist_day;
722	
723	  vp_sync_day();
724	  if (g_hist_day != before)
725	    {
726	      vp_status_write();
727	    }
728	}
