85	/****************************************************************************
86	 * Agent-readable persistence
87	 *
88	 * The on-device ai_agent needs real feeding data to summarise, and its
89	 * read_file tool is sandboxed to the agent data dir, so everything lands
90	 * under <agent data dir>/velapaw/:
91	 *
92	 *   history.bin  compact machine copy of the rolling window, reloaded at
93	 *                init so the history survives a reboot
94	 *   status.md    the digest a skill reads: per-pet totals, baseline,
95	 *                appetite %, body condition, drop alert
96	 *   feed_log.md  append-only recent events, size-capped
97	 *
98	 * Doing this from the velapaw task directly is safe: since the ai_agent
99	 * merge every task stack is carved from the XTENSA_IMEM heap and lives in
100	 * internal SRAM (measured: velapaw StackBase 0x3fcabc98), so a littlefs
101	 * write no longer runs with the stack sitting behind the disabled flash
102	 * cache -- the freeze that identity.c's worker thread exists to dodge.
103	 * If a stack ever moves back to PSRAM (0x3c......), these calls must move
104	 * onto that worker-thread pattern too.
105	 *
106	 * Every write is best-effort.  If /data is not mounted the calls fail
107	 * quietly and the in-memory analytics behave exactly as they did before.
108	 ****************************************************************************/
109	
110	#ifdef CONFIG_EXAMPLES_AI_AGENT_VELA_DATA_DIR
111	#  define VP_AGENT_DIR CONFIG_EXAMPLES_AI_AGENT_VELA_DATA_DIR
112	#else
113	#  define VP_AGENT_DIR "/data/ai_agent"
114	#endif
115	
116	#define VP_DIR      VP_AGENT_DIR "/velapaw"
117	#define VP_HISTORY  VP_DIR "/history.bin"
118	#define VP_STATUS   VP_DIR "/status.md"
119	#define VP_FEEDLOG  VP_DIR "/feed_log.md"
120	
121	/* read_file tops out at 32 KB and the /data partition is under 1 MB. */
122	#define VP_LOG_MAX  8192
123	#define VP_MAGIC_V1 0x56503031u        /* "VP01" -- before the day stamp */
124	#define VP_MAGIC    0x56503032u        /* "VP02" */
125	
126	/* Below this the realtime clock is clearly unset; printing a 1970 date
127	 * would mislead the model, so the raw epoch is logged instead. */
128	#define VP_TS_SANE  1600000000
129	
130	static bool g_fs_ready;
131	
132	static bool vp_ensure_dir(void)
133	{
134	  if (g_fs_ready)
135	    {
136	      return true;
137	    }
138	
139	  if (mkdir(VP_AGENT_DIR, 0755) != 0 && errno != EEXIST)
140	    {
141	      return false;
142	    }
143	
144	  if (mkdir(VP_DIR, 0755) != 0 && errno != EEXIST)
145	    {
146	      return false;
147	    }
148	
149	  g_fs_ready = true;
150	  return true;
151	}
152	
153	static void vp_history_save(void)
154	{
155	  if (!vp_ensure_dir())
156	    {
157	      return;
158	    }
159	
160	  FILE *f = fopen(VP_HISTORY, "wb");
161	  if (f == NULL)
162	    {
163	      return;
164	    }
165	
166	  /* hdr[3] is the civil day owning slot TODAY, -1 when unknown. */
167	  uint32_t hdr[4] =
168	    {
169	      VP_MAGIC, VELAPAW_MAX_PETS, DAYS, (uint32_t)(int32_t)g_hist_day
170	    };
171	
172	  if (fwrite(hdr, sizeof(hdr), 1, f) == 1)
173	    {
174	      fwrite(g_day_g, sizeof(g_day_g), 1, f);
175	      fwrite(g_day_m, sizeof(g_day_m), 1, f);
176	      fwrite(g_bcs,   sizeof(g_bcs),   1, f);
177	    }
178	
179	  fclose(f);
180	}
181	
182	static void vp_history_load(void)
183	{
184	  FILE *f = fopen(VP_HISTORY, "rb");
185	  if (f == NULL)
186	    {
187	      return;
188	    }
189	
190	  uint32_t hdr[4];
191	  bool ok;
192	
193	  /* Geometry is part of the format: a rebuild that changes MAX_PETS or the
194	   * window length invalidates the file instead of misreading it. */
195	  ok = fread(hdr, sizeof(uint32_t), 3, f) == 3
196	       && hdr[1] == VELAPAW_MAX_PETS
197	       && hdr[2] == DAYS;
198	
199	  if (ok && hdr[0] == VP_MAGIC)
200	    {
201	      ok = fread(&hdr[3], sizeof(uint32_t), 1, f) == 1;
202	      g_hist_day = ok ? (long)(int32_t)hdr[3] : -1;
203	    }
204	  else if (ok && hdr[0] == VP_MAGIC_V1)
205	    {
206	      /* Pre-day-stamp file: the arrays are still good, the day simply was
207	       * never recorded.  vp_sync_day() adopts today without shifting,
208	       * rather than guessing and throwing real days away. */
209	      g_hist_day = -1;
210	    }
211	  else
212	    {
213	      ok = false;
214	    }
215	
216	  if (ok)
217	    {
218	      if (fread(g_day_g, sizeof(g_day_g), 1, f) != 1
219	          || fread(g_day_m, sizeof(g_day_m), 1, f) != 1
220	          || fread(g_bcs, sizeof(g_bcs), 1, f) != 1)
221	        {
222	          /* Short or corrupt: a clean slate beats a half-loaded history. */
223	          memset(g_day_g, 0, sizeof(g_day_g));
224	          memset(g_day_m, 0, sizeof(g_day_m));
225	          for (int i = 0; i < VELAPAW_MAX_PETS; i++)
226	            {
227	              g_bcs[i] = -1;
228	            }
229	
230	          vp_say("velapaw/store: %s corrupt, history reset\n", VP_HISTORY);
231	        }
232	      else
233	        {
234	          vp_say("velapaw/store: history restored from %s\n", VP_HISTORY);
235	        }
236	    }
237	
238	  fclose(f);
239	}
