572	int velapaw_store_day_total(velapaw_pet_id_t id, int day_back)
573	{
574	  if (!valid(id) || day_back < 0 || day_back >= DAYS)
575	    {
576	      return 0;
577	    }
578	  return g_day_g[id][TODAY - day_back];
