import json, sys
# usage: find_msgs.py <jsonl> <needle> [max]
path, needle = sys.argv[1], sys.argv[2]
mx = int(sys.argv[3]) if len(sys.argv) > 3 else 5
hits = []
with open(path, encoding="utf-8") as f:
    for n, line in enumerate(f, 1):
        try:
            o = json.loads(line)
        except Exception:
            continue
        if o.get("type") not in ("user", "assistant"):
            continue
        msg = o.get("message") or {}
        c = msg.get("content")
        texts = []
        if isinstance(c, str):
            texts.append(c)
        elif isinstance(c, list):
            for b in c:
                if isinstance(b, dict) and b.get("type") == "text":
                    texts.append(b.get("text", ""))
        for t in texts:
            if needle in t:
                hits.append((n, o.get("type"), o.get("timestamp"), t))
for n, ty, ts, t in hits[-mx:]:
    print("=" * 30, n, ty, ts)
    print(t)

