241	static void vp_status_write(void)
242	{
243	  static const char *bcs_txt[] =
244	    {
245	      "under", "ideal", "over"
246	    };
247	
248	  if (!vp_ensure_dir())
249	    {
250	      return;
251	    }
252	
253	  FILE *f = fopen(VP_STATUS, "w");
254	  if (f == NULL)
255	    {
256	      return;
257	    }
258	
259	  fputs("# VelaPaw Feeding Status\n\n", f);
260	  fprintf(f, "Rolling %d-day window. Grams dispensed by the feeder to each "
261	             "recognised pet.\n\n", DAYS);
262	
263	  int n = velapaw_identity_count();
264	  if (n <= 0)
265	    {
266	      fputs("No pets enrolled yet.\n", f);
267	      fclose(f);
268	      return;
269	    }
270	
271	  for (velapaw_pet_id_t id = 0; id < n && id < VELAPAW_MAX_PETS; id++)
272	    {
273	      const struct velapaw_pet *p = velapaw_identity_get(id);
274	      const char *name = (p != NULL && p->name[0]) ? p->name : "(unnamed)";
275	      int b = g_bcs[id];
276	
277	      fprintf(f, "## %s\n", name);
278	      fprintf(f, "- today: %d g in %d meal(s)\n",
279	              velapaw_store_today_total(id), velapaw_store_today_meals(id));
280	      fprintf(f, "- last 7 days: %d g\n", velapaw_store_week_total(id));
281	      fprintf(f, "- baseline (average of prior days): %d g/day\n",
282	              velapaw_store_baseline_g(id));
283	      fprintf(f, "- appetite today: %d%% of baseline\n",
284	              velapaw_store_appetite_pct(id));
285	      fprintf(f, "- body condition: %s\n",
286	              (b >= 0 && b <= 2) ? bcs_txt[b] : "not scored");
287	      fprintf(f, "- owner daily limit: %d g\n", p != NULL ? p->daily_limit_g : 0);
288	      /* The agent has no tool that reads meal times -- it reads this file.
289	       * Publishing them here is what makes a get_meal_schedule tool
290	       * unnecessary, which keeps the tool-schema budget intact.
291	       */
292	
293	      fputs("- scheduled meals:", f);
294	
295	      for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
296	        {
297	          int m = (p != NULL) ? p->meal_min[k] : -1;
298	
299	          if (m < 0)
300	            {
301	              fputs(" off", f);
302	            }
303	          else
304	            {
305	              fprintf(f, " %02d:%02d", m / 60, m % 60);
306	            }
307	        }
308	
309	      fputs("\n", f);
310	
311	      if (velapaw_store_alert_drop(id))
312	        {
313	          fputs("- ALERT: intake on the last completed day was under half "
314	                "the baseline, an early illness sign worth flagging to the "
315	                "owner\n", f);
316	        }
317	
318	      fputs("\n", f);
319	    }
320	
321	  fclose(f);
322	}
