378	
379	/****************************************************************************
380	 * Day stamping
381	 *
382	 * The window is an array whose last slot is "today", so something has to
383	 * move it.  Until now the only thing that did was the EV_NEXTDAY demo
384	 * button, which means a board left running past midnight kept adding to the
385	 * same slot for ever.  Over-reporting intake makes the feeder withhold real
386	 * meals, so this is the dangerous direction to get wrong.
387	 ****************************************************************************/
388	
389	static long vp_days_from_civil(int y, unsigned m, unsigned d)
390	{
391	  /* Exact day number across month and year boundaries.  tm_yday alone is
392	   * not enough: 12-31 -> 01-01 has to be a delta of 1, not -364.
393	   */
394	  y -= m <= 2;
395	  long era = (y >= 0 ? y : y - 399) / 400;
396	  unsigned yoe = (unsigned)(y - era * 400);
397	  unsigned doy = (153 * (m + (m > 2 ? -3 : 9)) + 2) / 5 + d - 1;
398	  unsigned doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
399	  return era * 146097 + (long)doe - 719468;
400	}
401	
402	static long vp_today_num(void)
403	{
404	  time_t now = time(NULL);
405	  struct tm tmv;
406	
407	  /* Same sanity floor the feed log uses: an unset clock must never be
408	   * allowed to shift real history.
409	   */
410	  if (now < VP_TS_SANE)
411	    {
412	      return -1;
413	    }
414	
415	  localtime_r(&now, &tmv);
416	  return vp_days_from_civil(tmv.tm_year + 1900, tmv.tm_mon + 1, tmv.tm_mday);
417	}
418	
419	static void vp_shift_days(int n)
420	{
421	  if (n <= 0)
422	    {
423	      return;
424	    }
425	
426	  if (n > DAYS)
427	    {
428	      n = DAYS;
429	    }
430	
431	  for (int p = 0; p < VELAPAW_MAX_PETS; p++)
432	    {
433	      int d = 0;
434	      for (; d < DAYS - n; d++)
435	        {
436	          g_day_g[p][d] = g_day_g[p][d + n];
437	          g_day_m[p][d] = g_day_m[p][d + n];
438	        }
439	
440	      for (; d < DAYS; d++)
441	        {
442	          g_day_g[p][d] = 0;
443	          g_day_m[p][d] = 0;
444	        }
445	    }
446	}
447	
448	/* Reconcile the window with the wall clock.  Safe on every path that
449	 * touches the history -- it is a no-op within a single day.
450	 */
451	static void vp_sync_day(void)
452	{
453	  long today = vp_today_num();
454	
455	  if (today < 0)
456	    {
457	      return;              /* clock unusable -- leave the window alone */
458	    }
459	
460	  if (g_hist_day < 0)
461	    {
462	      /* First run, or a VP01 file: the data in the window is real, we just
463	       * never knew which day it belonged to.  Adopt today, do not shift.
464	       */
465	      g_hist_day = today;
466	      vp_history_save();
467	      return;
468	    }
469	
470	  if (today <= g_hist_day)
471	    {
472	      /* Same day, or the clock jumped backwards -- which the build-date
473	       * boot anchor does on every cold start.  Never shift backwards: it
474	       * would drop real days off the front and zero slots that hold data.
475	       */
476	      return;
477	    }
478	
479	  vp_shift_days((int)(today - g_hist_day));
480	  g_hist_day = today;
481	  vp_history_save();
482	}
483	
484	int velapaw_store_init(void)
485	{
486	  memset(g_day_g, 0, sizeof(g_day_g));
487	  memset(g_day_m, 0, sizeof(g_day_m));
488	  for (int i = 0; i < VELAPAW_MAX_PETS; i++)
489	    {
490	      g_bcs[i] = -1;
491	    }
492	
493	  vp_history_load();
494	
495	  /* A board that has been off -- or simply running -- across midnight has
496	   * to shift before it reports anything.
497	   */
498	  vp_sync_day();
499	
500	  /* Write the digest at startup too.  Without this, status.md does not exist
501	   * until the next feed, enroll or BCS update, so a freshly booted board
502	   * gives the agent's skill nothing to read. */
503	  vp_status_write();
504	  return 0;
505	}
