606	/* Alert on the most recent *completed* day (yesterday = TODAY-1) vs the
607	 * baseline of the days before it: a >50% drop is the early illness sign.
608	 */
609	int velapaw_store_alert_drop(velapaw_pet_id_t id)
610	{
611	  if (!valid(id) || DAYS < 3)
612	    {
613	      return 0;
614	    }
615	  int last = g_day_g[id][TODAY - 1];
616	  int sum = 0;
617	  for (int d = 0; d < TODAY - 1; d++)
618	    {
619	      sum += g_day_g[id][d];
620	    }
621	  int base = sum / (DAYS - 2);
622	  return (base > 0 && last * 2 < base) ? 1 : 0;
623	}
624	
625	void velapaw_store_seed(velapaw_pet_id_t id, int daily_g)
626	{
627	  if (!valid(id) || daily_g <= 0)
628	    {
629	      return;
630	    }
631	  /* fill the prior days with a normal baseline (deterministic +/- noise);
632	   * leave today (TODAY) at 0 so live feeding fills it in.
633	   */
634	  for (int d = 0; d < TODAY; d++)
635	    {
636	      int noise = ((id * 3 + d * 5) % 21) - 10;   /* -10..+10 g */
637	      int g = daily_g + noise;
638	      g_day_g[id][d] = g > 0 ? g : 0;
639	      g_day_m[id][d] = 2 + ((id + d) % 3);          /* 2..4 meals */
640	    }
641	
642	  /* Seeding happens at enrollment, which is the first moment a pet exists
643	   * to write a digest about. */
644	  vp_persist();
645	}
