647	void velapaw_store_roll_day(void)
648	{
649	  vp_shift_days(1);
650	
651	  /* Keep the stamp in step, or the next clock reconcile would shift a
652	   * second time for the same day.
653	   */
654	  if (g_hist_day >= 0)
655	    {
656	      g_hist_day++;
657	    }
658	
659	  vp_persist();
660	}
