770	/* Minutes until this pet may eat again, 0 = now.  Two meals can be due at
771	 * once (one was missed, or after a reset), and now that recognition wakes by
772	 * itself the second followed the first within seconds.  g_last_fed was meant
773	 * to space them, but nothing ever read it. */
774	static int feed_wait_min(int id, long today, int nowm)
775	{
776	  int wait_min = 0;
777	
778	  for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
779	    {
780	      int ago = nowm - g_meal_fed_min[id][k];
781	
782	      if (g_meal_fed_day[id][k] == today && g_meal_fed_g[id][k] > 0 &&
783	          ago >= 0 && ago < FEED_GAP_MIN && FEED_GAP_MIN - ago > wait_min)
784	        {
785	          wait_min = FEED_GAP_MIN - ago;
786	        }
787	    }
788	
789	  return wait_min;
790	}
