2028	/* Delete a pet, keeping every per-pet table in step.
2029	 *
2030	 * Pet ids ARE array indices, so velapaw_identity_delete() renumbers every pet
2031	 * after the deleted one. Anything keyed by id must shift the same way or the
2032	 * data ends up on the wrong animal: the feeding history (store), the meal
2033	 * timeline tables here, and any id we're currently holding. */
2034	static void do_delete_pet(velapaw_pet_id_t id)
2035	{
2036	  int n = velapaw_identity_count();
2037	  int p, k;
2038	
2039	  if (id < 0 || id >= n)
2040	    {
2041	      return;
2042	    }
2043	
2044	  /* shift this file's per-pet tables down over the deleted slot */
2045	  for (p = id; p < VELAPAW_MAX_PETS - 1; p++)
2046	    {
2047	      for (k = 0; k < VELAPAW_MAX_MEALS; k++)
2048	        {
2049	          g_meal_fed_day[p][k] = g_meal_fed_day[p + 1][k];
2050	          g_meal_fed_min[p][k] = g_meal_fed_min[p + 1][k];
2051	          g_meal_fed_g[p][k]   = g_meal_fed_g[p + 1][k];
2052	          g_meal_skipped[p][k] = g_meal_skipped[p + 1][k];
2053	        }
2054	      g_last_fed[p] = g_last_fed[p + 1];
2055	    }
2056	  for (k = 0; k < VELAPAW_MAX_MEALS; k++)
2057	    {
2058	      g_meal_fed_day[VELAPAW_MAX_PETS - 1][k] = 0;   /* 0 = never fed */
2059	      g_meal_fed_min[VELAPAW_MAX_PETS - 1][k] = 0;
2060	      g_meal_fed_g[VELAPAW_MAX_PETS - 1][k]   = 0;
2061	      g_meal_skipped[VELAPAW_MAX_PETS - 1][k] = 0;
2062	    }
2063	  g_last_fed[VELAPAW_MAX_PETS - 1] = 0;
2064	
2065	  velapaw_store_delete(id);            /* history + BCS, shifted to match */
2066	  velapaw_identity_delete(id);         /* the pet itself + icon, renumbers rest */
2067	  velapaw_identity_save();             /* persist: stays deleted after reset */
2068	  velapaw_identity_save_icons();       /* icons were shifted too */
2069	  fed_save();                          /* and today's meals */
2070	
2071	  /* velapaw_store_delete() above wrote status.md while the pet still existed,
2072	   * pairing every later name with the next pet's history.  Rewrite it now that
2073	   * the names have shifted too. */
2074	  velapaw_store_status_refresh();
2075	
2076	  /* every id we were holding may now point at a different pet */
2077	  g_fed_visit = VELAPAW_PET_UNKNOWN;
2078	  g_bcs_for   = VELAPAW_PET_UNKNOWN;
2079	  g_cand      = VELAPAW_PET_UNKNOWN;
2080	  g_stable    = 0;
2081	
2082	  n = velapaw_identity_count();
2083	  if (g_trend_pet >= n) g_trend_pet = (n > 0) ? n - 1 : 0;
2084	  g_petn = n;
2085	
2086	  uprintf("velapaw/ui: deleted pet %d (%d left)\n", (int)id, n);
2087	}
