1362	
1363	/* % of today's ration eaten: today / daily_limit (0..100, since feeding stops
1364	 * at the limit). 100% = ate its full daily allowance. */
1365	static int pet_appetite_pct(velapaw_pet_id_t id, const struct velapaw_pet *p)
1366	{
1367	  int today = velapaw_store_today_total(id);
1368	  int pct = (p->daily_limit_g > 0) ? today * 100 / p->daily_limit_g : 100;
1369	  return (pct > 100) ? 100 : pct;   /* limit is a cap: never over 100% */
1370	}
1371	
1372	/* appetite-drop alert: the last completed day was under half the daily limit. */
1373	static int pet_alert_drop(velapaw_pet_id_t id, const struct velapaw_pet *p)
1374	{
1375	  int yesterday = velapaw_store_day_total(id, 1);
1376	  return (p->daily_limit_g > 0 && yesterday * 2 < p->daily_limit_g) ? 1 : 0;
1377	}
