1418	static void do_capture(void)
1419	{
1420	  if (g_nsamp >= MAX_SHOTS)
1421	    {
1422	      return;
1423	    }
1424	  if (g_inf_state != 0 || g_cap_pending)
1425	    {
1426	      return;                       /* an inference is already in flight */
1427	    }
1428	
1429	  /* Grab the frame here (cheap, ~ms), but hand the INFERENCE to the worker.
1430	   * Running embed() inline on this task wedged the SoC -- see the note on the
1431	   * worker state above. The loop picks the result up when g_inf_state == 3. */
1432	  cam_grab(&g_inf_frame);
1433	  g_inf_mode    = 1;                /* enroll capture: embed, don't match */
1434	  g_cap_pending = 1;
1435	  g_inf_state   = 1;                /* -> worker */
1436	  lv_label_set_text(g_sample_lbl, T(S_CAPTURING));
1437	}
