5080	                          g_bcs_votes[0] = g_bcs_votes[1] = g_bcs_votes[2] = 0;
5081	                          g_bcs_nvotes = 0;
5082	                        }
5083	                      if (g_bcs_nvotes < BCS_VOTES)
5084	                        {
5085	                          int bcls = -1;
5086	                          float bconf = 0.0f;
5087	                          int brc;
5088	
5089	                          /* under the TFLM lock like every other Invoke: the
5090	                           * voice worker's KWS shares the ESP-NN kernels */
5091	                          g_ui_at = "bcs";
5092	                          pthread_mutex_lock(&g_tflm_lock);
5093	                          brc = velapaw_infer_bcs(&frame, &bcls, &bconf);
5094	                          pthread_mutex_unlock(&g_tflm_lock);
5095	                          g_ui_at = "recog";
5096	                          if (brc == 0 && bcls >= 0 && bcls < 3)
5097	                            {
5098	                              g_bcs_votes[bcls]++;
5099	                              g_bcs_nvotes++;
5100	                              int best = 0;
5101	                              if (g_bcs_votes[1] > g_bcs_votes[best]) best = 1;
5102	                              if (g_bcs_votes[2] > g_bcs_votes[best]) best = 2;
5103	                              velapaw_store_set_bcs(m.id, best);  /* running majority */
5104	                            }
5105	                        }
5106	#endif
5107	                      /* ---- MODEL B: recognition-gated SCHEDULED feeding ----
5108	                       * Recognition decides WHO is at the bowl; the pet's meal
5109	                       * time decides WHEN it may eat. Food is dispensed only if
5110	                       * the meal is due and this pet hasn't eaten it today. */
5111	                      long today = wall_day();
5112	                      int  nowm  = wall_min();
5113	                      int  has_meal = 0;    /* any slot configured?           */
5114	                      int  slot     = -1;   /* a slot that is DUE and unfed   */
5115	                      int  pending  = -1;   /* soonest slot still ahead today */
5116	                      for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
5117	                        {
5118	                          int mm = pet->meal_min[k];
5119	                          if (mm < 0) continue;
5120	                          has_meal = 1;
5121	                          if (g_meal_fed_day[m.id][k] == today) continue; /* eaten */
5122	                          if (g_meal_skipped[m.id][k]) continue; /* owner skipped it */
5123	                          if (nowm >= mm)
5124	                            {
5125	                              /* due: prefer the latest due slot we haven't eaten */
5126	                              if (slot < 0 || mm > pet->meal_min[slot]) slot = k;
5127	                            }
5128	                          else if (pending < 0 || mm < pet->meal_min[pending])
5129	                            {
5130	                              pending = k;   /* next meal still to come */
5131	                            }
5132	                        }
5133	                      int due = (slot >= 0);
5134	
5135	                      if (due)
5136	                        {
5137	                          int rest = feed_wait_min(m.id, today, nowm);
5138	
5139	                          if (velapaw_store_today_total(m.id) >=
5140	                              pet->daily_limit_g)
5141	                            {
5142	                              /* closed with nothing served: My Pets shows it
5143	                               * as skipped, not as eaten */
5144	                              g_meal_fed_day[m.id][slot] = today;  /* don't re-try */
5145	                              g_meal_fed_min[m.id][slot] = nowm;
5146	                              g_meal_fed_g[m.id][slot]   = 0;
5147	                              fed_save();
5148	                              lv_obj_set_style_text_color(g_sub,
5149	                                  lv_color_hex(COL_COOL), 0);
5150	                              lv_label_set_text_fmt(g_sub, T(S_LIMIT_HIT_FMT),
5151	                                  velapaw_store_today_total(m.id),
5152	                                  pet->daily_limit_g);
5153	                            }
5154	                          else if (rest > 0)
5155	                            {
5156	                              /* it has just eaten another meal: this one waits */
5157	                              int at = nowm + rest;
5158	
5159	                              lv_obj_set_style_text_color(g_sub,
5160	                                  lv_color_hex(COL_COOL), 0);
5161	                              lv_label_set_text_fmt(g_sub, T(S_NEXT_MEAL_FMT),
5162	                                  (at / 60) % 24, at % 60);
5163	                            }
5164	                          else
5165	                            {
5166	                              /* trim the serving so today never exceeds the cap */
5167	                              int remaining = pet->daily_limit_g -
5168	                                  velapaw_store_today_total(m.id);
5169	                              int amount = (pet->portion_g < remaining)
5170	                                           ? pet->portion_g : remaining;
5171	
5172	                              /* Mark and save the meal before the motor turns: if
5173	                               * anything after this hangs and the board is reset,
5174	                               * the meal must not be served twice. */
5175	                              g_last_fed[m.id]           = mono_ms() / 1000;
5176	                              g_meal_fed_day[m.id][slot] = today;  /* this meal done */
5177	                              g_meal_fed_min[m.id][slot] = nowm;   /* ...at this time */
5178	                              g_meal_fed_g[m.id][slot]   = amount; /* ...this much */
5179	                              fed_save();
5180	                              g_ui_at = g_at_feed;
5181	                              velapaw_feeder_dispense(amount);
5182	                              g_ui_at = "store";
5183	                              { struct timespec _w;
5184	                                clock_gettime(CLOCK_REALTIME, &_w);
5185	                                struct velapaw_feed_event ev2 =
5186	                                  { m.id, (time_t)_w.tv_sec,   /* real wall-clock time */
5187	                                    amount, m.score, g_be->name };
5188	                                velapaw_store_log_feeding(&ev2); }
5189	                              g_ui_at = "recog";
5190	                              lv_obj_set_style_text_color(g_sub,
5191	                                  lv_color_hex(COL_FED), 0);
5192	                              lv_label_set_text_fmt(g_sub, T(S_FED_FMT), amount,
5193	                                  slot + 1, VELAPAW_MAX_MEALS,
5194	                                  velapaw_store_today_total(m.id),
5195	                                  pet->daily_limit_g);
5196	                            }
5197	                        }
5198	                      else if (!has_meal)
5199	                        {
5200	                          lv_obj_set_style_text_color(g_sub, lv_color_hex(COL_DIM), 0);
5201	                          lv_label_set_text(g_sub, T(S_NO_MEALS));
5202	                        }
5203	                      else if (pending >= 0)
5204	                        {
5205	                          lv_obj_set_style_text_color(g_sub, lv_color_hex(COL_COOL), 0);
5206	                          lv_label_set_text_fmt(g_sub, T(S_NEXT_MEAL_FMT),
5207	                                                pet->meal_min[pending] / 60,
5208	                                                pet->meal_min[pending] % 60);
5209	                        }
5210	                      else
5211	                        {
5212	                          lv_obj_set_style_text_color(g_sub, lv_color_hex(COL_FED), 0);
5213	                          lv_label_set_text_fmt(g_sub, T(S_ALL_EATEN_FMT),
5214	                              velapaw_store_today_total(m.id));

1	/****************************************************************************
2	 * VelaPaw - in-memory store backend (emulator) + feeding-behavior analytics
3	 *
4	 * Keeps a rolling 7-day history of grams + meal counts per pet (index
5	 * DAYS-1 == today). Powers daily/weekly intake, meal frequency, appetite
6	 * baseline/trend, and the sudden-appetite-drop alert. Replace with a
7	 * persistent backend (apps/system/settings or littlefs) on hardware so
8	 * history survives reboots.
9	 ****************************************************************************/
10	
11	#include <stdio.h>
12	#include <stdarg.h>
13	#include <string.h>
14	#include <stdbool.h>
15	#include <stdint.h>
16	#include <errno.h>
17	#include <fcntl.h>
18	#include <time.h>
19	#include <unistd.h>
20	#include <sys/ioctl.h>
21	#include <sys/stat.h>
22	#include "store/store.h"
23	#include "identity/identity.h"
24	
25	#define DAYS VELAPAW_HIST_DAYS
26	#define TODAY (DAYS - 1)
27	
28	static int g_day_g[VELAPAW_MAX_PETS][DAYS];      /* grams per day */
29	static int g_day_m[VELAPAW_MAX_PETS][DAYS];      /* meals per day */
30	static int g_bcs[VELAPAW_MAX_PETS];              /* last BCS: 0/1/2, -1 none */
31	
32	/* Civil day number (see vp_days_from_civil) that owns slot TODAY, or -1
33	 * when it is not known yet: an unset clock, or a pre-VP02 history file.
34	 */
35	static long g_hist_day = -1;
36	
37	static int valid(velapaw_pet_id_t id)
38	{
39	  return id >= 0 && id < VELAPAW_MAX_PETS;
40	}
