1	/****************************************************************************
2	 * VelaPaw - in-memory store backend (emulator) + feeding-behavior analytics
3	 *
4	 * Keeps a rolling 7-day history of grams + meal counts per pet (index
5	 * DAYS-1 == today). Powers daily/weekly intake, meal frequency, appetite
6	 * baseline/trend, and the sudden-appetite-drop alert. Replace with a
7	 * persistent backend (apps/system/settings or littlefs) on hardware so
8	 * history survives reboots.
9	 ****************************************************************************/
10	
11	#include <stdio.h>
12	#include <stdarg.h>
13	#include <string.h>
14	#include <stdbool.h>
15	#include <stdint.h>
16	#include <errno.h>
17	#include <fcntl.h>
18	#include <time.h>
19	#include <unistd.h>
20	#include <sys/ioctl.h>
21	#include <sys/stat.h>
22	#include "store/store.h"
23	#include "identity/identity.h"
24	
25	#define DAYS VELAPAW_HIST_DAYS
26	#define TODAY (DAYS - 1)
27	
28	static int g_day_g[VELAPAW_MAX_PETS][DAYS];      /* grams per day */
29	static int g_day_m[VELAPAW_MAX_PETS][DAYS];      /* meals per day */
30	static int g_bcs[VELAPAW_MAX_PETS];              /* last BCS: 0/1/2, -1 none */
31	
32	/* Civil day number (see vp_days_from_civil) that owns slot TODAY, or -1
33	 * when it is not known yet: an unset clock, or a pre-VP02 history file.
34	 */
35	static long g_hist_day = -1;
36	
37	static int valid(velapaw_pet_id_t id)
38	{
39	  return id >= 0 && id < VELAPAW_MAX_PETS;
40	}
41	
42	/* A console line that is dropped, not waited for, when the host has stopped
43	 * reading.  Same rule as con_ok() in ui/ui_lvgl.c, which explains why a
44	 * plain printf can block the UI thread for good.
45	 */
46	static void vp_say(const char *fmt, ...) __attribute__((format(printf, 1, 2)));
47	static void vp_say(const char *fmt, ...)
48	{
49	  char line[128];
50	  va_list ap;
51	  int n;
52	
53	  va_start(ap, fmt);
54	  n = vsnprintf(line, sizeof(line), fmt, ap);
55	  va_end(ap);
56	  if (n <= 0)
57	    {
58	      return;
59	    }
60	
61	  if (n > (int)sizeof(line) - 1)
62	    {
63	      n = sizeof(line) - 1;
64	    }
65	
66	#ifdef FIONSPACE
67	  for (int i = 0; i < 5; i++)
68	    {
69	      int room;
70	
71	      if (ioctl(STDOUT_FILENO, FIONSPACE, (unsigned long)(uintptr_t)&room) < 0
72	          || room >= n)
73	        {
74	          write(STDOUT_FILENO, line, n);
75	          return;
76	        }
77	
78	      usleep(10000);
79	    }
80	#else
81	  write(STDOUT_FILENO, line, n);
82	#endif
83	}
84	
85	/****************************************************************************
86	 * Agent-readable persistence
87	 *
88	 * The on-device ai_agent needs real feeding data to summarise, and its
89	 * read_file tool is sandboxed to the agent data dir, so everything lands
90	 * under <agent data dir>/velapaw/:
91	 *
92	 *   history.bin  compact machine copy of the rolling window, reloaded at
93	 *                init so the history survives a reboot
94	 *   status.md    the digest a skill reads: per-pet totals, baseline,
95	 *                appetite %, body condition, drop alert
96	 *   feed_log.md  append-only recent events, size-capped
97	 *
98	 * Doing this from the velapaw task directly is safe: since the ai_agent
99	 * merge every task stack is carved from the XTENSA_IMEM heap and lives in
100	 * internal SRAM (measured: velapaw StackBase 0x3fcabc98), so a littlefs
101	 * write no longer runs with the stack sitting behind the disabled flash
102	 * cache -- the freeze that identity.c's worker thread exists to dodge.
103	 * If a stack ever moves back to PSRAM (0x3c......), these calls must move
104	 * onto that worker-thread pattern too.
105	 *
106	 * Every write is best-effort.  If /data is not mounted the calls fail
107	 * quietly and the in-memory analytics behave exactly as they did before.
108	 ****************************************************************************/
109	
110	#ifdef CONFIG_EXAMPLES_AI_AGENT_VELA_DATA_DIR
111	#  define VP_AGENT_DIR CONFIG_EXAMPLES_AI_AGENT_VELA_DATA_DIR
112	#else
113	#  define VP_AGENT_DIR "/data/ai_agent"
114	#endif
115	
116	#define VP_DIR      VP_AGENT_DIR "/velapaw"
117	#define VP_HISTORY  VP_DIR "/history.bin"
118	#define VP_STATUS   VP_DIR "/status.md"
119	#define VP_FEEDLOG  VP_DIR "/feed_log.md"
120	
121	/* read_file tops out at 32 KB and the /data partition is under 1 MB. */
122	#define VP_LOG_MAX  8192
123	#define VP_MAGIC_V1 0x56503031u        /* "VP01" -- before the day stamp */
124	#define VP_MAGIC    0x56503032u        /* "VP02" */
125	
126	/* Below this the realtime clock is clearly unset; printing a 1970 date
127	 * would mislead the model, so the raw epoch is logged instead. */
128	#define VP_TS_SANE  1600000000
129	
130	static bool g_fs_ready;
131	
132	static bool vp_ensure_dir(void)
133	{
134	  if (g_fs_ready)
135	    {
136	      return true;
137	    }
138	
139	  if (mkdir(VP_AGENT_DIR, 0755) != 0 && errno != EEXIST)
140	    {
141	      return false;
142	    }
143	
144	  if (mkdir(VP_DIR, 0755) != 0 && errno != EEXIST)
145	    {
146	      return false;
147	    }
148	
149	  g_fs_ready = true;
150	  return true;
151	}
152	
153	static void vp_history_save(void)
154	{
155	  if (!vp_ensure_dir())
156	    {
157	      return;
158	    }
159	
160	  FILE *f = fopen(VP_HISTORY, "wb");
161	  if (f == NULL)
162	    {
163	      return;
164	    }
165	
166	  /* hdr[3] is the civil day owning slot TODAY, -1 when unknown. */
167	  uint32_t hdr[4] =
168	    {
169	      VP_MAGIC, VELAPAW_MAX_PETS, DAYS, (uint32_t)(int32_t)g_hist_day
170	    };
171	
172	  if (fwrite(hdr, sizeof(hdr), 1, f) == 1)
173	    {
174	      fwrite(g_day_g, sizeof(g_day_g), 1, f);
175	      fwrite(g_day_m, sizeof(g_day_m), 1, f);
176	      fwrite(g_bcs,   sizeof(g_bcs),   1, f);
177	    }
178	
179	  fclose(f);
180	}
181	
182	static void vp_history_load(void)
183	{
184	  FILE *f = fopen(VP_HISTORY, "rb");
185	  if (f == NULL)
186	    {
187	      return;
188	    }
189	
190	  uint32_t hdr[4];
191	  bool ok;
192	
193	  /* Geometry is part of the format: a rebuild that changes MAX_PETS or the
194	   * window length invalidates the file instead of misreading it. */
195	  ok = fread(hdr, sizeof(uint32_t), 3, f) == 3
196	       && hdr[1] == VELAPAW_MAX_PETS
197	       && hdr[2] == DAYS;
198	
199	  if (ok && hdr[0] == VP_MAGIC)
200	    {
201	      ok = fread(&hdr[3], sizeof(uint32_t), 1, f) == 1;
202	      g_hist_day = ok ? (long)(int32_t)hdr[3] : -1;
203	    }
204	  else if (ok && hdr[0] == VP_MAGIC_V1)
205	    {
206	      /* Pre-day-stamp file: the arrays are still good, the day simply was
207	       * never recorded.  vp_sync_day() adopts today without shifting,
208	       * rather than guessing and throwing real days away. */
209	      g_hist_day = -1;
210	    }
211	  else
212	    {
213	      ok = false;
214	    }
215	
216	  if (ok)
217	    {
218	      if (fread(g_day_g, sizeof(g_day_g), 1, f) != 1
219	          || fread(g_day_m, sizeof(g_day_m), 1, f) != 1
220	          || fread(g_bcs, sizeof(g_bcs), 1, f) != 1)
221	        {
222	          /* Short or corrupt: a clean slate beats a half-loaded history. */
223	          memset(g_day_g, 0, sizeof(g_day_g));
224	          memset(g_day_m, 0, sizeof(g_day_m));
225	          for (int i = 0; i < VELAPAW_MAX_PETS; i++)
226	            {
227	              g_bcs[i] = -1;
228	            }
229	
230	          vp_say("velapaw/store: %s corrupt, history reset\n", VP_HISTORY);
231	        }
232	      else
233	        {
234	          vp_say("velapaw/store: history restored from %s\n", VP_HISTORY);
235	        }
236	    }
237	
238	  fclose(f);
239	}
240	
241	static void vp_status_write(void)
242	{
243	  static const char *bcs_txt[] =
244	    {
245	      "under", "ideal", "over"
246	    };
247	
248	  if (!vp_ensure_dir())
249	    {
250	      return;
251	    }
252	
253	  FILE *f = fopen(VP_STATUS, "w");
254	  if (f == NULL)
255	    {
256	      return;
257	    }
258	
259	  fputs("# VelaPaw Feeding Status\n\n", f);
260	  fprintf(f, "Rolling %d-day window. Grams dispensed by the feeder to each "
261	             "recognised pet.\n\n", DAYS);
262	
263	  int n = velapaw_identity_count();
264	  if (n <= 0)
265	    {
266	      fputs("No pets enrolled yet.\n", f);
267	      fclose(f);
268	      return;
269	    }
270	
271	  for (velapaw_pet_id_t id = 0; id < n && id < VELAPAW_MAX_PETS; id++)
272	    {
273	      const struct velapaw_pet *p = velapaw_identity_get(id);
274	      const char *name = (p != NULL && p->name[0]) ? p->name : "(unnamed)";
275	      int b = g_bcs[id];
276	
277	      fprintf(f, "## %s\n", name);
278	      fprintf(f, "- today: %d g in %d meal(s)\n",
279	              velapaw_store_today_total(id), velapaw_store_today_meals(id));
280	      fprintf(f, "- last 7 days: %d g\n", velapaw_store_week_total(id));
281	      fprintf(f, "- baseline (average of prior days): %d g/day\n",
282	              velapaw_store_baseline_g(id));
283	      fprintf(f, "- appetite today: %d%% of baseline\n",
284	              velapaw_store_appetite_pct(id));
285	      fprintf(f, "- body condition: %s\n",
286	              (b >= 0 && b <= 2) ? bcs_txt[b] : "not scored");
287	      fprintf(f, "- owner daily limit: %d g\n", p != NULL ? p->daily_limit_g : 0);
288	      /* The agent has no tool that reads meal times -- it reads this file.
289	       * Publishing them here is what makes a get_meal_schedule tool
290	       * unnecessary, which keeps the tool-schema budget intact.
291	       */
292	
293	      fputs("- scheduled meals:", f);
294	
295	      for (int k = 0; k < VELAPAW_MAX_MEALS; k++)
296	        {
297	          int m = (p != NULL) ? p->meal_min[k] : -1;
298	
299	          if (m < 0)
300	            {
301	              fputs(" off", f);
302	            }
303	          else
304	            {
305	              fprintf(f, " %02d:%02d", m / 60, m % 60);
306	            }
307	        }
308	
309	      fputs("\n", f);
310	
311	      if (velapaw_store_alert_drop(id))
312	        {
313	          fputs("- ALERT: intake on the last completed day was under half "
314	                "the baseline, an early illness sign worth flagging to the "
315	                "owner\n", f);
316	        }
317	
318	      fputs("\n", f);
319	    }
320	
321	  fclose(f);
322	}
