581	/* average of the prior days (everything except today) */
582	int velapaw_store_baseline_g(velapaw_pet_id_t id)
583	{
584	  if (!valid(id))
585	    {
586	      return 0;
587	    }
588	  int sum = 0;
589	  for (int d = 0; d < TODAY; d++)
590	    {
591	      sum += g_day_g[id][d];
592	    }
593	  return sum / (DAYS - 1);
594	}
