245	/* ---- wall clock -----------------------------------------------------------
246	 * Software CLOCK_REALTIME (no hardware RTC: enabling it killed the USB console,
247	 * so the clock is set by the user each session via Set Clock and starts at a
248	 * sane default). LOCALTIME is off, so derive HH:MM straight from epoch seconds
249	 * and treat that as local time. */
250	static int wall_min(void)          /* minute-of-day, 0..1439 */
251	{
252	  struct timespec ts;
253	  clock_gettime(CLOCK_REALTIME, &ts);
254	  return (int)((ts.tv_sec % 86400) / 60);
255	}
256	static long wall_day(void)         /* day number (for per-day "fed" resets) */
257	{
258	  struct timespec ts;
259	  clock_gettime(CLOCK_REALTIME, &ts);
260	  return (long)(ts.tv_sec / 86400);
261	}
