803	    {
804	      const struct velapaw_pet *p = velapaw_identity_get(i);
805	
806	      for (int k = 0; p != NULL && k < VELAPAW_MAX_MEALS; k++)
807	        {
808	          int since = nowm - p->meal_min[k];
809	
810	          if (p->meal_min[k] >= 0 && since >= 0 &&
811	              since < MEAL_POLL_WIN_MIN &&
812	              g_meal_fed_day[i][k] != today && !g_meal_skipped[i][k])
813	            {
814	              return 1;
815	            }
816	        }
817	    }
818	
819	  return 0;
820	}
