2028	/* Delete a pet, keeping every per-pet table in step.
2029	 *
2030	 * Pet ids ARE array indices, so velapaw_identity_delete() renumbers every pet
2031	 * after the deleted one. Anything keyed by id must shift the same way or the
2032	 * data ends up on the wrong animal: the feeding history (store), the meal
2033	 * timeline tables here, and any id we're currently holding. */
2034	static void do_delete_pet(velapaw_pet_id_t id)
2035	{
2036	  int n = velapaw_identity_count();
2037	  int p, k;
2038	
2039	  if (id < 0 || id >= n)
2040	    {
2041	      return;
2042	    }
2043	
2044	  /* shift this file's per-pet tables down over the deleted slot */
2045	  for (p = id; p < VELAPAW_MAX_PETS - 1; p++)
2046	    {
2047	      for (k = 0; k < VELAPAW_MAX_MEALS; k++)
2048	        {
2049	          g_meal_fed_day[p][k] = g_meal_fed_day[p + 1][k];
2050	          g_meal_fed_min[p][k] = g_meal_fed_min[p + 1][k];
2051	          g_meal_fed_g[p][k]   = g_meal_fed_g[p + 1][k];
2052	          g_meal_skipped[p][k] = g_meal_skipped[p + 1][k];
2053	        }
2054	      g_last_fed[p] = g_last_fed[p + 1];
2055	    }
2056	  for (k = 0; k < VELAPAW_MAX_MEALS; k++)
2057	    {
