544	int velapaw_store_week_total(velapaw_pet_id_t id)
545	{
546	  if (!valid(id))
547	    {
548	      return 0;
549	    }
550	  int sum = 0;
551	  for (int d = 0; d < VELAPAW_WEEK_DAYS && d <= TODAY; d++)
552	    {
553	      sum += g_day_g[id][TODAY - d];   /* last 7 days incl. today */
554	    }
