559	{
560	  if (!valid(id))
561	    {
562	      return 0;
563	    }
564	  int sum = 0;
565	  for (int d = 0; d < DAYS; d++)
566	    {
567	      sum += g_day_g[id][d];
568	    }
569	  return sum;
