596	int velapaw_store_appetite_pct(velapaw_pet_id_t id)
597	{
598	  int base = velapaw_store_baseline_g(id);
599	  if (base <= 0)
600	    {
601	      return 100;
602	    }
603	  return g_day_g[id][TODAY] * 100 / base;
604	}
