132	static bool vp_ensure_dir(void)
133	{
134	  if (g_fs_ready)
135	    {
136	      return true;
137	    }
138	
139	  if (mkdir(VP_AGENT_DIR, 0755) != 0 && errno != EEXIST)
140	    {
141	      return false;
142	    }
143	
144	  if (mkdir(VP_DIR, 0755) != 0 && errno != EEXIST)
145	    {
146	      return false;
147	    }
148	
149	  g_fs_ready = true;
150	  return true;
151	}
