153	static void vp_history_save(void)
154	{
155	  if (!vp_ensure_dir())
156	    {
157	      return;
158	    }
159	
160	  FILE *f = fopen(VP_HISTORY, "wb");
161	  if (f == NULL)
162	    {
163	      return;
164	    }
165	
166	  /* hdr[3] is the civil day owning slot TODAY, -1 when unknown. */
167	  uint32_t hdr[4] =
168	    {
169	      VP_MAGIC, VELAPAW_MAX_PETS, DAYS, (uint32_t)(int32_t)g_hist_day
170	    };
171	
172	  if (fwrite(hdr, sizeof(hdr), 1, f) == 1)
173	    {
174	      fwrite(g_day_g, sizeof(g_day_g), 1, f);
175	      fwrite(g_day_m, sizeof(g_day_m), 1, f);
176	      fwrite(g_bcs,   sizeof(g_bcs),   1, f);
177	    }
178	
179	  fclose(f);
180	}
181	
182	static void vp_history_load(void)
183	{
184	  FILE *f = fopen(VP_HISTORY, "rb");
185	  if (f == NULL)
186	    {
187	      return;
188	    }
189	
190	  uint32_t hdr[4];
191	  bool ok;
192	
193	  /* Geometry is part of the format: a rebuild that changes MAX_PETS or the
194	   * window length invalidates the file instead of misreading it. */
195	  ok = fread(hdr, sizeof(uint32_t), 3, f) == 3
196	       && hdr[1] == VELAPAW_MAX_PETS
197	       && hdr[2] == DAYS;
198	
199	  if (ok && hdr[0] == VP_MAGIC)
200	    {
201	      ok = fread(&hdr[3], sizeof(uint32_t), 1, f) == 1;
202	      g_hist_day = ok ? (long)(int32_t)hdr[3] : -1;
203	    }
204	  else if (ok && hdr[0] == VP_MAGIC_V1)
205	    {
206	      /* Pre-day-stamp file: the arrays are still good, the day simply was
207	       * never recorded.  vp_sync_day() adopts today without shifting,
208	       * rather than guessing and throwing real days away. */
209	      g_hist_day = -1;
210	    }
211	  else
212	    {
213	      ok = false;
214	    }
215	
216	  if (ok)
217	    {
218	      if (fread(g_day_g, sizeof(g_day_g), 1, f) != 1
219	          || fread(g_day_m, sizeof(g_day_m), 1, f) != 1
220	          || fread(g_bcs, sizeof(g_bcs), 1, f) != 1)
221	        {
222	          /* Short or corrupt: a clean slate beats a half-loaded history. */
223	          memset(g_day_g, 0, sizeof(g_day_g));
224	          memset(g_day_m, 0, sizeof(g_day_m));
225	          for (int i = 0; i < VELAPAW_MAX_PETS; i++)
226	            {
227	              g_bcs[i] = -1;
228	            }
229	
230	          vp_say("velapaw/store: %s corrupt, history reset\n", VP_HISTORY);
231	        }
232	      else
233	        {
234	          vp_say("velapaw/store: history restored from %s\n", VP_HISTORY);
235	        }
236	    }
237	
238	  fclose(f);
239	}
