507	int velapaw_store_log_feeding(const struct velapaw_feed_event *ev)
508	{
509	  if (ev == NULL || !valid(ev->pet_id))
510	    {
511	      return -1;
512	    }
513	
514	  /* Bucket the event in the right day even if the board has been up since
515	   * before midnight.
516	   */
517	  vp_sync_day();
518	
519	  g_day_g[ev->pet_id][TODAY] += ev->grams;
520	  g_day_m[ev->pet_id][TODAY] += 1;
521	
522	  /* Save first, print last.  The console can block for good when the host
523	   * stops reading it, and a meal that was dispensed but never saved is fed
524	   * again after the reset that follows. */
525	
526	  vp_feedlog_append(ev);
527	  vp_persist();
528	
529	  vp_say("    [store] event pet=%d grams=%d score=%.2f model=%s\n",
530	         ev->pet_id, ev->grams, ev->score, ev->model ? ev->model : "?");
531	  return 0;
532	}
