662	/* Drop a pet's history and shift the rest down. Pet ids are array indices, so
663	 * velapaw_identity_delete() renumbers every later pet -- this keeps the history
664	 * attached to the right animal instead of silently inheriting it. */
665	void velapaw_store_delete(velapaw_pet_id_t id)
666	{
667	  if (!valid(id))
668	    {
669	      return;
670	    }
671	
672	  for (int p = id; p < VELAPAW_MAX_PETS - 1; p++)
673	    {
674	      memcpy(g_day_g[p], g_day_g[p + 1], sizeof(g_day_g[0]));
675	      memcpy(g_day_m[p], g_day_m[p + 1], sizeof(g_day_m[0]));
676	      g_bcs[p] = g_bcs[p + 1];
677	    }
678	
679	  memset(g_day_g[VELAPAW_MAX_PETS - 1], 0, sizeof(g_day_g[0]));
680	  memset(g_day_m[VELAPAW_MAX_PETS - 1], 0, sizeof(g_day_m[0]));
681	  g_bcs[VELAPAW_MAX_PETS - 1] = -1;
682	
683	  vp_persist();
684	}
