479	/* Reconcile the window with the wall clock.  Safe on every path that
480	 * touches the history -- it is a no-op within a single day.
481	 */
482	static void vp_sync_day(void)
483	{
484	  long today = vp_today_num();
485	
486	  if (today < 0)
487	    {
488	      return;              /* clock unusable -- leave the window alone */
489	    }
490	
491	  if (g_hist_day < 0)
492	    {
493	      /* First run, or a VP01 file: the data in the window is real, we just
494	       * never knew which day it belonged to.  Adopt today, do not shift.
495	       */
496	      g_hist_day = today;
497	      vp_history_save();
498	      return;
499	    }
500	
501	  if (today <= g_hist_day)
502	    {
503	      /* Same day, or the clock jumped backwards -- which the build-date
504	       * boot anchor does on every cold start.  Never shift backwards: it
505	       * would drop real days off the front and zero slots that hold data.
506	       */
507	      return;
508	    }
509	
510	  vp_shift_days((int)(today - g_hist_day));
511	  g_hist_day = today;
512	  vp_history_save();
513	}
