653	/* Started just before the UI loop, not earlier: a boot that wedges would
654	 * otherwise turn into a reset loop that floods health.log. */
655	static void stall_start(void)
656	{
657	  struct sched_param sp;
658	  pthread_attr_t attr;
659	  pthread_t tid;
660	  int prio = 100;
661	  int pmax = sched_get_priority_max(SCHED_FIFO);
662	  int ok = 0;
663	
664	  if (sched_getparam(0, &sp) == 0)
665	    {
666	      prio = sp.sched_priority;
667	    }
668	
669	  if (pmax > 10 && prio > pmax - 10)
670	    {
671	      prio = pmax - 10;
672	    }
673	
674	  pthread_attr_init(&attr);
675	  pthread_attr_setinheritsched(&attr, PTHREAD_EXPLICIT_SCHED);
676	
677	  pthread_attr_setstacksize(&attr, 2048);
678	  sp.sched_priority = prio + 10;
679	  pthread_attr_setschedparam(&attr, &sp);
680	  if (pthread_create(&tid, &attr, stall_monitor, NULL) == 0)
681	    {
682	      pthread_detach(tid);
683	      ok++;
684	    }
685	
686	  pthread_attr_setstacksize(&attr, 6144);
687	  sp.sched_priority = prio + 5;
688	  pthread_attr_setschedparam(&attr, &sp);
689	  if (pthread_create(&tid, &attr, stall_note, NULL) == 0)
690	    {
691	      pthread_detach(tid);
692	      ok++;
693	    }
694	
695	  pthread_attr_destroy(&attr);
696	  uprintf("velapaw: stall monitor %s\n", ok == 2 ? "armed" : "NOT started");
697	}
