"""Print a .docx body as numbered blocks: paragraph style, list level, text, tables.

Usage: python -I dump.py <in.docx> <out.txt>
"""
import sys
import zipfile
import xml.etree.ElementTree as ET

W = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"

src, dst = sys.argv[1:3]
z = zipfile.ZipFile(src)
doc = ET.fromstring(z.read("word/document.xml"))
styles = ET.fromstring(z.read("word/styles.xml"))
names = {s.get(W + "styleId"): (s.find(W + "name").get(W + "val") if s.find(W + "name") is not None else "?")
         for s in styles.iter(W + "style")}


def para_text(p):
    out = []
    for el in p.iter():
        if el.tag == W + "t":
            out.append(el.text or "")
        elif el.tag == W + "tab":
            out.append("\t")
        elif el.tag == W + "br":
            out.append(" / ")
        elif el.tag == W + "instrText":
            out.append("{FIELD:" + (el.text or "").strip() + "}")
    return "".join(out)


def para_info(p):
    ppr = p.find(W + "pPr")
    style, lvl = "", ""
    if ppr is not None:
        ps = ppr.find(W + "pStyle")
        if ps is not None:
            style = ps.get(W + "val")
        num = ppr.find(W + "numPr")
        if num is not None:
            il = num.find(W + "ilvl")
            ni = num.find(W + "numId")
            lvl = f"list{ni.get(W + 'val') if ni is not None else '?'}.{il.get(W + 'val') if il is not None else 0}"
    extra = []
    if p.find(".//" + W + "drawing") is not None:
        extra.append("[IMAGE]")
    if any(el.tag == W + "br" and el.get(W + "type") == "page" for el in p.iter()):
        extra.append("[PAGEBREAK]")
    return style, lvl, " ".join(extra)


lines = []
body = doc.find(W + "body")
n = 0
for child in body:
    n += 1
    if child.tag == W + "p":
        style, lvl, extra = para_info(child)
        label = names.get(style, style) if style else "Normal"
        lines.append(f"[{n}] P<{label}{' ' + lvl if lvl else ''}>{' ' + extra if extra else ''} {para_text(child)}")
    elif child.tag == W + "tbl":
        lines.append(f"[{n}] TABLE")
        for r, tr in enumerate(child.iter(W + "tr")):
            cells = [" ".join(para_text(p) for p in tc.iter(W + "p")).strip() for tc in tr.findall(W + "tc")]
            lines.append(f"    r{r}: " + " | ".join(cells))
    elif child.tag == W + "sectPr":
        lines.append(f"[{n}] SECTPR")
    else:
        lines.append(f"[{n}] {child.tag.replace(W, 'w:')}")

used = sorted({para_info(p)[0] for p in body.iter(W + "p")} - {""})
lines.append("== styles used ==")
lines += [f"{s} = {names.get(s, '?')}" for s in used]
lines.append("== parts ==")
lines += [f"{i.filename} {i.file_size}" for i in z.infolist()]
open(dst, "w", encoding="utf-8").write("\n".join(lines) + "\n")
print(f"{n} body blocks -> {dst}")

