n = 0
for child in body:
    n += 1
    if child.tag == W + "p":
        style, lvl, extra = para_info(child)
        label = names.get(style, style) if style else "Normal"
        lines.append(f"[{n}] P<{label}{' ' + lvl if lvl else ''}>{' ' + extra if extra else ''} {para_text(child)}")
    elif child.tag == W + "tbl":
        lines.append(f"[{n}] TABLE")
        for r, tr in enumerate(child.iter(W + "tr")):
            cells = [" ".join(para_text(p) for p in tc.iter(W + "p")).strip() for tc in tr.findall(W + "tc")]
            lines.append(f"    r{r}: " + " | ".join(cells))
    elif child.tag == W + "sectPr":
        lines.append(f"[{n}] SECTPR")
    else:
        lines.append(f"[{n}] {child.tag.replace(W, 'w:')}")

used = sorted({para_info(p)[0] for p in body.iter(W + "p")} - {""})
lines.append("== styles used ==")
lines += [f"{s} = {names.get(s, '?')}" for s in used]
lines.append("== parts ==")
lines += [f"{i.filename} {i.file_size}" for i in z.infolist()]
open(dst, "w", encoding="utf-8").write("\n".join(lines) + "\n")
print(f"{n} body blocks -> {dst}")

"""Raw-string access to word/document.xml: body blocks, table rows/cells, text.

Edits work on the XML text itself, so the document is never reserialised and
every other part of the package is copied byte for byte.
"""
import re
import zipfile
from xml.sax.saxutils import unescape

TAG = re.compile(r"<(/?)([A-Za-z0-9_]+:[A-Za-z0-9_]+)\b[^>]*?(/?)>")
TEXT = re.compile(r"<w:t(?:\s[^>]*)?>([^<]*)</w:t>")


def load(path):
    z = zipfile.ZipFile(path)
    infos = z.infolist()
    parts = {i.filename: z.read(i.filename) for i in infos}
    z.close()
    return infos, parts, parts["word/document.xml"].decode("utf-8")


def save(path, infos, parts, xml):
    parts = dict(parts)
    parts["word/document.xml"] = xml.encode("utf-8")
    with zipfile.ZipFile(path, "w") as out:
        for i in infos:
            out.writestr(i, parts[i.filename])  # same name, date, compression, order


def element_end(xml, s):
    """End offset of the element whose open tag starts at s."""
    m = TAG.match(xml, s)
    if m.group(3):
        return m.end()
    depth = 0
    for t in TAG.finditer(xml, s):
        if t.group(1):
            depth -= 1
            if depth == 0:
                return t.end()
        elif not t.group(3):
            depth += 1
    raise ValueError("unclosed element at %d" % s)


def children(xml, s, e=None):
    """Direct children of the element at s: list of (name, start, end)."""
    if e is None:
        e = element_end(xml, s)
    m = TAG.match(xml, s)
    out, depth, cur = [], 0, None
    for t in TAG.finditer(xml, m.end(), e):
        closing, name, selfclose = t.group(1), t.group(2), t.group(3)
        if closing:
            depth -= 1
            if depth == 0:
                out.append((cur[0], cur[1], t.end()))
            elif depth < 0:
                break
        elif selfclose:
            if depth == 0:
                out.append((name, t.start(), t.end()))
        else:
            if depth == 0:
                cur = (name, t.start())
            depth += 1
    return out


def body_blocks(xml):
    """Top-level body children, numbered from 1 like dump.py."""
    b = xml.index("<w:body>")
    return children(xml, b)


def text(frag):
    return "".join(unescape(t) for t in TEXT.findall(frag))

