"""Compact run-by-run view of body blocks, with an rPr legend.

Usage: python -I runs.py <in.docx> <spec>[,<spec>...] [maxtext]
  spec = <block#> | <block#>.r<row#> | <from>-<to>
"""
import os
import re
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import docxraw  # noqa: E402

sys.stdout.reconfigure(encoding="utf-8")
path, specs = sys.argv[1:3]
maxtext = int(sys.argv[3]) if len(sys.argv) > 3 else 160
_, _, xml = docxraw.load(path)
blocks = docxraw.body_blocks(xml)
legend = {}


def rpr_id(r):
    m = re.search(r"<w:rPr>.*?</w:rPr>", r)
    key = m.group(0) if m else "-"
    if key not in legend:
        legend[key] = f"R{len(legend)}"
    return legend[key]


def show_para(s, e, indent):
    p = xml[s:e]
    ppr = re.match(r"<w:p\b[^>]*>(<w:pPr>.*?</w:pPr>)?", p, re.S).group(1) or ""
    style = re.search(r'<w:pStyle w:val="([^"]+)"', ppr)
    num = re.search(r'<w:numId w:val="(\d+)"', ppr)
    print(f"{indent}P {style.group(1) if style else 'Normal'}{' num' + num.group(1) if num else ''}")
    for name, rs, re_ in docxraw.children(xml, s, e):
        if name != "w:r":
            if name != "w:pPr":
                print(f"{indent}  <{name}>")
            continue
        r = xml[rs:re_]
        marks = "".join(m for m, t in (("/", "<w:br/>"), ("¶", "lastRenderedPageBreak")) if t in r)
        print(f"{indent}  {rpr_id(r)}{marks} {docxraw.text(r)[:maxtext]!r}")


def show(name, s, e, indent=""):
    if name == "w:p":
        show_para(s, e, indent)
    elif name in ("w:tbl", "w:tr", "w:tc"):
        for cn, cs, ce in docxraw.children(xml, s, e):
            if cn in ("w:tr", "w:tc", "w:p"):
                if cn == "w:tr":
                    print(f"{indent}-- row")
                show(cn, cs, ce, indent + "  ")


for spec in specs.split(","):
    if ".r" in spec:
        bn, rn = spec.split(".r")
        _, s, e = blocks[int(bn) - 1]
        rows = [c for c in docxraw.children(xml, s, e) if c[0] == "w:tr"]
        print(f"=== [{bn}] row {rn}")
        show(*rows[int(rn)])
    else:
        lo, _, hi = spec.partition("-")
        for n in range(int(lo), int(hi or lo) + 1):
            print(f"=== [{n}]")
            show(*blocks[n - 1])
print("== rPr legend ==")
for k, v in legend.items():
    print(v, k)

