# Find Chinese punctuation that Word lays out at a line edge: closing marks starting a line,
# opening marks ending one. Prints the two lines around each break.
#
# Usage: powershell -File edgescan.ps1 -Out <report.txt> <a.docx> [<b.docx> ...]
param([Parameter(Mandatory = $true)][string]$Out,
      [Parameter(Mandatory = $true, ValueFromRemainingArguments = $true)][string[]]$Paths)

[Console]::OutputEncoding = [Text.Encoding]::UTF8
$p = $null; try { $p = Get-Process WINWORD -ErrorAction Stop } catch {}
if ($null -ne $p) { "WINWORD is already running - not starting the scan"; return }

$closers = -join [char[]](0xFF09, 0x3002, 0xFF0C, 0xFF1B, 0xFF1A, 0x3001, 0xFF01, 0xFF1F, 0x201D, 0x300B)
$openers = -join [char[]](0xFF08, 0x201C, 0x300A)
$skip = @("`r", "`n", [string][char]7, [string][char]11, [string][char]12)

function LineOf($w, $doc, $pos) {
  $sel = $w.Selection
  $sel.SetRange($pos, $pos + 1)
  [void]$sel.HomeKey(5); $a = $sel.Start
  [void]$sel.EndKey(5); $b = $sel.End
  return ($doc.Range($a, $b).Text -replace "[\r\n\a\v\f]", " ")
}

$report = New-Object System.Collections.Generic.List[string]
$w = New-Object -ComObject Word.Application; $w.Visible = $false; $w.DisplayAlerts = 0
try {
  foreach ($path in $Paths) {
    $doc = $w.Documents.Open($path, $false, $true, $false)
    $doc.ActiveWindow.View.Type = 3
    $hits = New-Object System.Collections.Generic.List[object]; $n = 0
    foreach ($ch in ($closers + $openers).ToCharArray()) {
      $isClose = $closers.IndexOf($ch) -ge 0
      $rng = $doc.Content; $f = $rng.Find
      $f.ClearFormatting(); $f.Text = [string]$ch; $f.Forward = $true; $f.Wrap = 0
      while ($f.Execute()) {
        $n++; $s = $rng.Start
        if ($isClose) { $o = $doc.Range($s - 1, $s) } else { $o = $doc.Range($s + 1, $s + 2) }
        if ($skip -notcontains $o.Text) {
          $p1 = $rng.Information(3); $p2 = $o.Information(3)
          $y1 = $rng.Information(6); $y2 = $o.Information(6)
          if ($p1 -ne $p2 -or [Math]::Abs($y1 - $y2) -gt 3) {
            $hits.Add([pscustomobject]@{ Pos = $s; Page = $p1; Close = $isClose })
          }
        }
        $rng.Collapse(0)
      }
    }
    $report.Add("== $path : $n marks checked, $($hits.Count) at a line edge")
    foreach ($h in ($hits | Sort-Object Pos)) {
      $upper = if ($h.Close) { $h.Pos - 1 } else { $h.Pos }
      $kind = if ($h.Close) { "START" } else { "END  " }
      $report.Add(("{0} p{1,-3} @{2}" -f $kind, $h.Page, $h.Pos))
      $report.Add("    | " + (LineOf $w $doc $upper))
      $report.Add("    | " + (LineOf $w $doc ($upper + 1)))
    }
    $doc.Close(0)
  }
}
finally { $w.Quit(); [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($w) }
[IO.File]::WriteAllLines($Out, $report, (New-Object Text.UTF8Encoding($false)))
$report

