# Pagination check: tables whose header row is cut off from row 2, and preformatted blocks
# (the text figures) that run over a page break. Also lists the page each table starts on.
#
# Usage: powershell -File layoutcheck.ps1 <a.docx> [<b.docx> ...]
param([Parameter(Mandatory = $true, ValueFromRemainingArguments = $true)][string[]]$Paths)

[Console]::OutputEncoding = [Text.Encoding]::UTF8
$p = $null; try { $p = Get-Process WINWORD -ErrorAction Stop } catch {}
if ($null -ne $p) { "WINWORD is already running - not starting the check"; return }

function StartPage($rng) { $r = $rng.Duplicate; $r.Collapse(1); return $r.Information(3) }

$w = New-Object -ComObject Word.Application; $w.Visible = $false; $w.DisplayAlerts = 0
try {
  foreach ($path in $Paths) {
    $doc = $w.Documents.Open($path, $false, $true, $false)
    $doc.ActiveWindow.View.Type = 3
    $doc.Repaginate()
    $cut = @(); $starts = @(); $i = 0
    foreach ($t in $doc.Tables) {
      $i++
      $pa = StartPage $t.Cell(1, 1).Range
      $starts += "$i`:p$pa"
      if ($t.Rows.Count -lt 2) { continue }
      $pb = StartPage $t.Cell(2, 1).Range
      if ($pa -ne $pb) { $cut += "  table $i header p$pa, row 2 p$pb ($($t.Cell(1, 1).Range.Text -replace '[\r\a]', ''))" }
    }
    $spans = @(); $blocks = 0; $first = $null; $last = $null; $head = ""
    foreach ($para in $doc.Paragraphs) {
      if ($para.Style.NameLocal -eq "HTML Preformatted") {
        if ($null -eq $first) { $first = StartPage $para.Range; $head = $para.Range.Text.Trim() }
        $last = $para.Range.Information(3)
      } elseif ($null -ne $first) {
        $blocks++
        if ($first -ne $last) { $spans += "  preformatted block p$first-p$last ($head)" }
        $first = $null
      }
    }
    "== $(Split-Path $path -Leaf): $($doc.ComputeStatistics(2)) pages; $($cut.Count) header rows cut off; $blocks preformatted blocks, $($spans.Count) over a page break"
    $cut; $spans
    "  table starts: " + ($starts -join " ")
    $doc.Close(0)
  }
} finally { $w.Quit(); [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($w) }

