def keep_headers():
    """Keep every table's header row with its first row, so the reflow never leaves one alone at a page foot."""
    n = 0
    for name, s, e in reversed(docxraw.body_blocks(doc)):
        rows = kids((s, e), "w:tr") if name == "w:tbl" else []
        if len(rows) < 2:
