        for tc in reversed(kids(rows[0], "w:tc")):
            for ps, _ in reversed(kids(tc, "w:p")):
                keep_next(ps)
    return n


def keep_blocks(limit=30):
    """Keep each preformatted block of up to limit lines on one page, together with the line that
    introduces it; longer blocks (Figure 3-2) split as they did in the preliminary edition."""
    blocks = docxraw.body_blocks(doc)
    style = [(PHEAD.match(doc, s).group(2) or "") if n == "w:p" else None for n, s, _ in blocks]
    pre = [st is not None and 'w:val="HTMLPreformatted"' in st for st in style]
    targets, n, k = [], 0, 0
    while k < len(blocks):
        j = k
        while pre[k] and j + 1 < len(blocks) and pre[j + 1]:
            j += 1
        if pre[k] and j - k < limit:
            n += 1
            targets += range(k, j)
            if k and style[k - 1] is not None and not re.search(r'<w:pStyle w:val="heading', style[k - 1], re.I):
                targets.append(k - 1)
        k = j + 1
    for k in sorted(targets, reverse=True):
        keep_next(blocks[k][1])
    return n

