# Pagination check. Reports what a page break has cut off: a table header row from row 2, a
# table from the paragraph that introduces it, a heading from what follows it, a caption from
# what it captions, and preformatted blocks (the text figures) that run over a page.
#
# Usage: powershell -File layoutcheck.ps1 <a.docx> [<b.docx> ...]
param([Parameter(Mandatory = $true, ValueFromRemainingArguments = $true)][string[]]$Paths)

[Console]::OutputEncoding = [Text.Encoding]::UTF8
$p = $null; try { $p = Get-Process WINWORD -ErrorAction Stop } catch {}
if ($null -ne $p) { "WINWORD is already running - not starting the check"; return }

function StartPage($rng) { $r = $rng.Duplicate; $r.Collapse(1); return $r.Information(3) }
function Short($s) { $s = ($s -replace '[\r\a\v]', ' ').Trim(); return $s.Substring(0, [Math]::Min(60, $s.Length)) }

$w = New-Object -ComObject Word.Application; $w.Visible = $false; $w.DisplayAlerts = 0
try {
  foreach ($path in $Paths) {
    $doc = $w.Documents.Open($path, $false, $true, $false)
    $doc.ActiveWindow.View.Type = 3
    $doc.Repaginate()
    $cut = @(); $intro = @(); $starts = @(); $i = 0
    foreach ($t in $doc.Tables) {
      $i++
      $pa = StartPage $t.Cell(1, 1).Range
      $starts += "$i`:p$pa"
      $prev = $t.Range.Previous(4, 1)
      if ($null -ne $prev -and $prev.Information(3) -ne $pa) { $intro += "  table $i on p$pa, its intro on p$($prev.Information(3)): $(Short $prev.Text)" }
      if ($t.Rows.Count -lt 2) { continue }
      $pb = StartPage $t.Cell(2, 1).Range
      if ($pa -ne $pb) { $cut += "  table $i header p$pa, row 2 p$pb ($(Short $t.Cell(1, 1).Range.Text))" }
    }
    $heads = @(); $caps = @(); $spans = @(); $blocks = 0; $first = $null; $last = $null; $head = ""; $lines = 0; $split = ""
    foreach ($para in $doc.Paragraphs) {
      $name = $para.Style.NameLocal
      if ($name -like "heading *") {
        $nx = $para.Next(1)
        if ($null -ne $nx -and $para.Range.Information(3) -ne (StartPage $nx.Range)) { $heads += "  heading on p$($para.Range.Information(3)), next on p$(StartPage $nx.Range): $(Short $para.Range.Text)" }
      } elseif ($name -like "caption*") {
        $pv = $para.Previous(1)
        if ($null -ne $pv -and $pv.Range.Information(3) -ne (StartPage $para.Range)) { $caps += "  caption on p$(StartPage $para.Range), above it p$($pv.Range.Information(3)): $(Short $para.Range.Text)" }
      }
      if ($name -eq "HTML Preformatted") {
        $pg = StartPage $para.Range
        if ($null -eq $first) { $first = $pg; $head = ""; $lines = 0; $split = "" }
        elseif ($pg -ne $last -and $split -eq "") { $split = "after line $lines" }
        $lines++
        if ($head -eq "") { $head = Short $para.Range.Text }
        $last = $para.Range.Information(3)
        if ($last -ne $pg -and $split -eq "") { $split = "inside line $lines" }
      } elseif ($null -ne $first) {
        $blocks++
        $tag = "block $blocks p$first-p$last, $lines lines" + $(if ($split) { ", breaks $split" } else { "" }) + ": " + $head
        if ($first -ne $last) { $spans += "  $tag" } else { $spans += "  ($tag)" }
        $first = $null
      }
    }
    $over = @($spans | Where-Object { -not $_.StartsWith("  (") }).Count
    "== $(Split-Path $path -Leaf): $($doc.ComputeStatistics(2)) pages; cut off: $($cut.Count) header rows, $($intro.Count) table intros, $($heads.Count) headings, $($caps.Count) captions; $over of $blocks preformatted blocks over a page break"
    $cut; $intro; $heads; $caps; $spans
    "  table starts: " + ($starts -join " ")
    $doc.Close(0)
  }
} finally { $w.Quit(); [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($w) }

