# For each rendered page, find where the ink ends (as a share of the page height), to spot pages a
# keep-with-next chain has left with a large blank at the bottom. Prints only the pages that end
# above -Below, plus a count.
#
# Usage: powershell -File gaps.ps1 -Dir <png dir> [-Below 0.8]
param([Parameter(Mandatory = $true)][string]$Dir, [double]$Below = 0.80)

Add-Type -ReferencedAssemblies System.Drawing -TypeDefinition @"
using System.Drawing; using System.Drawing.Imaging; using System.Runtime.InteropServices;
public static class Ink {
  public static double[] Extent(string path) {
    using (var bmp = new Bitmap(path)) {
      var d = bmp.LockBits(new Rectangle(0, 0, bmp.Width, bmp.Height), ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
      var buf = new byte[d.Stride * bmp.Height]; Marshal.Copy(d.Scan0, buf, 0, buf.Length); bmp.UnlockBits(d);
      int x0 = bmp.Width / 20, x1 = bmp.Width - x0, first = -1, last = -1;
      for (int y = 0; y < bmp.Height; y++) {
        int o = y * d.Stride;
        for (int x = x0; x < x1; x++) { int i = o + 3 * x; if (buf[i] < 200 || buf[i + 1] < 200 || buf[i + 2] < 200) { if (first < 0) first = y; last = y; break; } }
      }
      return new double[] { (double)first / bmp.Height, (double)last / bmp.Height };
    }
  }
}
"@
$pages = @(Get-ChildItem (Join-Path $Dir "p*.png") | Sort-Object Name)
$early = 0
foreach ($f in $pages) {
  $e = [Ink]::Extent($f.FullName)
  if ($e[1] -lt $Below) { $early++; "  {0}: ink from {1:N0}% to {2:N0}%" -f $f.BaseName, (100 * $e[0]), (100 * $e[1]) }
}
"$(Split-Path $Dir -Leaf): $($pages.Count) pages, $early end above $([int](100 * $Below))%"

